// 歷史人物（中英雙語）· Famous people (bilingual). at: related city ids, first = main place; c/pl: birthplace when not a city on the map
window.PEOPLE=[
// ---- Ancient Near East & Mediterranean ----
{id:"hammurabi",y:[-1810,-1750],ca:1,at:["babylon"],n:{zh:"漢謨拉比",en:"Hammurabi"},r:{zh:"巴比倫國王",en:"King of Babylon"},d:{zh:"古巴比倫第一王朝的國王，統一了美索不達米亞南部，頒佈了現存最完整的古代法典之一《漢謨拉比法典》。",en:"King of the First Babylonian Dynasty who united southern Mesopotamia and issued the Code of Hammurabi, one of the most complete ancient law codes to survive."}},
{id:"ramesses-ii",y:[-1303,-1213],ca:1,at:["thebes"],n:{zh:"拉美西斯二世",en:"Ramesses II"},r:{zh:"埃及法老",en:"Pharaoh of Egypt"},d:{zh:"新王國第十九王朝的法老，在位六十餘年，與赫梯人在卡迭石交戰後簽訂了已知最早的和約之一，修建了阿布辛貝神廟。",en:"Pharaoh of the Nineteenth Dynasty who reigned for more than sixty years, fought the Hittites at Kadesh and later made one of the earliest known peace treaties with them, and built Abu Simbel."}},
{id:"tutankhamun",y:[-1341,-1323],ca:1,at:["thebes"],n:{zh:"圖坦卡蒙",en:"Tutankhamun"},r:{zh:"埃及法老",en:"Pharaoh of Egypt"},d:{zh:"第十八王朝的少年法老，恢復了阿蒙神崇拜；1922 年其幾乎完好的陵墓在帝王谷被發現。",en:"Boy pharaoh of the Eighteenth Dynasty who restored the worship of Amun; his almost intact tomb was found in the Valley of the Kings in 1922."}},
{id:"ashurbanipal",y:[-685,-631],ca:1,at:["nineveh"],n:{zh:"亞述巴尼拔",en:"Ashurbanipal"},r:{zh:"亞述國王",en:"King of Assyria"},d:{zh:"亞述帝國最後一位強大的君主，在尼尼微建立了收藏數萬塊泥板的圖書館，《吉爾伽美什史詩》因此得以保存。",en:"The last great king of Assyria, who gathered a library of tens of thousands of clay tablets at Nineveh, preserving among them the Epic of Gilgamesh."}},
{id:"nebuchadnezzar-ii",y:[-634,-562],ca:1,at:["babylon","jerusalem"],n:{zh:"尼布甲尼撒二世",en:"Nebuchadnezzar II"},r:{zh:"新巴比倫國王",en:"King of Babylon"},d:{zh:"新巴比倫王國最強盛的君主，攻滅猶大王國、焚燬耶路撒冷聖殿，並大規模營建巴比倫城與伊什塔爾城門。",en:"The most powerful king of the Neo-Babylonian Empire, who destroyed the kingdom of Judah and the Temple in Jerusalem and rebuilt Babylon with the Ishtar Gate."}},
{id:"cyrus-the-great",y:[-600,-530],ca:1,at:["babylon"],c:[53.17,30.20],pl:{en:"Pasargadae",zh:"帕薩爾加德"},n:{zh:"居魯士大帝",en:"Cyrus the Great"},r:{zh:"波斯阿契美尼德帝國創建者",en:"Founder of the Achaemenid Persian Empire"},d:{zh:"擊敗米底、呂底亞與巴比倫，建立了當時世界上最大的帝國；他允許被擄的猶太人返回故土。",en:"Conquered Media, Lydia and Babylon to build the largest empire the world had yet seen, and allowed the exiled Judeans to return home."}},
{id:"darius-i",y:[-550,-486],at:["babylon"],c:[52.89,29.93],pl:{en:"Persepolis",zh:"波斯波利斯"},n:{zh:"大流士一世",en:"Darius I"},r:{zh:"波斯國王",en:"King of Persia"},d:{zh:"阿契美尼德帝國的組織者，設立行省、修築御道、統一貨幣，興建波斯波利斯，並發動了第一次希波戰爭。",en:"Organiser of the Achaemenid Empire who created satrapies, built the Royal Road, standardised coinage, founded Persepolis and launched the first Persian invasion of Greece."}},
{id:"pericles",y:[-495,-429],at:["athens"],n:{zh:"伯里克利",en:"Pericles"},r:{zh:"雅典政治家",en:"Athenian statesman"},d:{zh:"雅典民主鼎盛時期的領袖，主持修建帕特農神廟，伯羅奔尼撒戰爭初期死於瘟疫。",en:"Leader of Athens at the height of its democracy who rebuilt the Acropolis with the Parthenon; he died of the plague early in the Peloponnesian War."}},
{id:"herodotus",y:[-484,-425],ca:1,at:["athens"],c:[27.43,37.04],pl:{en:"Halicarnassus",zh:"哈利卡納蘇斯"},n:{zh:"希羅多德",en:"Herodotus"},r:{zh:"歷史學家",en:"Historian"},d:{zh:"被稱為“歷史之父”，其《歷史》記述了希波戰爭以及他遊歷所見的各地風俗。",en:"Called the ‘Father of History’; his Histories tell the story of the Persian Wars and describe the peoples he met on his travels."}},
{id:"socrates",y:[-470,-399],at:["athens"],n:{zh:"蘇格拉底",en:"Socrates"},r:{zh:"哲學家",en:"Philosopher"},d:{zh:"雅典哲學家，以對話詰問探求倫理問題，未留下著作；被控“不敬神、腐蝕青年”，飲毒芹而死。",en:"Athenian philosopher who questioned his fellow citizens about how to live; he wrote nothing and was condemned to drink hemlock for impiety and corrupting the young."}},
{id:"plato",y:[-428,-348],ca:1,at:["athens","syracuse"],n:{zh:"柏拉圖",en:"Plato"},r:{zh:"哲學家",en:"Philosopher"},d:{zh:"蘇格拉底的學生，在雅典創辦學園，以對話體寫成《理想國》等著作，曾三次前往敘拉古。",en:"Pupil of Socrates who founded the Academy in Athens and wrote dialogues such as the Republic; he made three journeys to Syracuse."}},
{id:"aristotle",y:[-384,-322],at:["athens"],c:[23.77,40.53],pl:{en:"Stagira",zh:"斯塔吉拉"},n:{zh:"亞里士多德",en:"Aristotle"},r:{zh:"哲學家",en:"Philosopher"},d:{zh:"柏拉圖的學生、亞歷山大大帝的老師，在雅典創辦呂克昂學園，著述涵蓋邏輯、倫理、政治與自然科學。",en:"Pupil of Plato and tutor of Alexander the Great who founded the Lyceum in Athens and wrote on logic, ethics, politics and the natural world."}},
{id:"alexander-the-great",y:[-356,-323],at:["babylon","alexandria","tyre"],c:[22.52,40.76],pl:{en:"Pella",zh:"佩拉"},n:{zh:"亞歷山大大帝",en:"Alexander the Great"},r:{zh:"馬其頓國王",en:"King of Macedon"},d:{zh:"二十歲繼承馬其頓王位，十餘年間征服波斯帝國直至印度河，建立多座亞歷山大城，三十二歲死於巴比倫。",en:"King of Macedon at twenty who conquered the Persian Empire as far as the Indus within a decade, founded many Alexandrias and died at Babylon aged thirty-two."}},
{id:"euclid",y:[-325,-265],ca:1,at:["alexandria"],n:{zh:"歐幾里得",en:"Euclid"},r:{zh:"數學家",en:"Mathematician"},d:{zh:"亞歷山大城的數學家，所著《幾何原本》以公理推導定理，兩千年來一直是幾何學的標準教材。",en:"Mathematician of Alexandria whose Elements derived geometry from axioms and remained the standard textbook for two thousand years."}},
{id:"archimedes",y:[-287,-212],ca:1,at:["syracuse","alexandria"],n:{zh:"阿基米德",en:"Archimedes"},r:{zh:"數學家、發明家",en:"Mathematician and inventor"},d:{zh:"敘拉古的數學家和工程師，發現浮力原理並計算圓周率近似值；羅馬攻陷敘拉古時被殺。",en:"Mathematician and engineer of Syracuse who discovered the principle of buoyancy and estimated pi; he was killed when Rome took the city."}},
{id:"hannibal",y:[-247,-183],ca:1,at:["carthage"],n:{zh:"漢尼拔",en:"Hannibal"},r:{zh:"迦太基統帥",en:"Carthaginian general"},d:{zh:"第二次布匿戰爭中率軍翻越阿爾卑斯山進入意大利，在坎尼大勝羅馬，最終在扎馬戰敗。",en:"Led an army across the Alps into Italy in the Second Punic War and crushed Rome at Cannae, but was finally defeated at Zama."}},
{id:"cicero",y:[-106,-43],at:["rome"],n:{zh:"西塞羅",en:"Cicero"},r:{zh:"演說家、政治家",en:"Orator and statesman"},d:{zh:"羅馬共和國晚期最著名的演說家和文體家，反對凱撒與安東尼，在後三頭同盟的清洗中被殺。",en:"The greatest orator and prose stylist of the late Roman Republic; he opposed Caesar and Antony and was killed in the proscriptions of the Second Triumvirate."}},
{id:"julius-caesar",y:[-100,-44],at:["rome","alexandria"],n:{zh:"尤利烏斯·凱撒",en:"Julius Caesar"},r:{zh:"羅馬統帥、獨裁官",en:"Roman general and dictator"},d:{zh:"征服高盧後渡過盧比孔河發動內戰，成為終身獨裁官，公元前 44 年 3 月 15 日在元老院遇刺。",en:"Conquered Gaul, crossed the Rubicon to win a civil war and became dictator for life; he was assassinated in the Senate on the Ides of March, 44 BC."}},
{id:"virgil",y:[-70,-19],at:["rome","naples"],n:{zh:"維吉爾",en:"Virgil"},r:{zh:"詩人",en:"Poet"},d:{zh:"奧古斯都時代的羅馬詩人，史詩《埃涅阿斯紀》講述羅馬的起源，葬於那不勒斯。",en:"Roman poet of the Augustan age whose epic, the Aeneid, tells the legendary origins of Rome; he was buried at Naples."}},
{id:"cleopatra",y:[-69,-30],at:["alexandria","rome"],n:{zh:"克婁巴特拉七世",en:"Cleopatra VII"},r:{zh:"埃及女王",en:"Queen of Egypt"},d:{zh:"托勒密王朝末代女王，先後與凱撒和安東尼結盟；亞克興戰敗後自盡，埃及併入羅馬。",en:"Last ruler of Ptolemaic Egypt, allied in turn with Caesar and Mark Antony; after defeat at Actium she took her own life and Egypt became Roman."}},
{id:"augustus",y:[-63,14],at:["rome"],n:{zh:"奧古斯都",en:"Augustus"},r:{zh:"羅馬第一位皇帝",en:"First Roman emperor"},d:{zh:"凱撒的養子，擊敗安東尼後建立元首制，開啟兩百年的“羅馬和平”。",en:"Caesar’s adopted heir who defeated Antony, founded the Principate and began two centuries of the Pax Romana."}},
{id:"jesus",y:[-4,30],ca:1,at:["jerusalem"],c:[35.30,32.70],pl:{en:"Nazareth",zh:"拿撒勒"},n:{zh:"耶穌",en:"Jesus of Nazareth"},r:{zh:"基督教的核心人物",en:"Central figure of Christianity"},d:{zh:"加利利的猶太傳道者，在羅馬總督彼拉多治下於耶路撒冷被釘十字架；其追隨者形成了基督教。",en:"Jewish preacher from Galilee who was crucified in Jerusalem under the Roman governor Pontius Pilate; his followers founded Christianity."}},
{id:"ptolemy",y:[100,170],ca:1,at:["alexandria"],n:{zh:"托勒密",en:"Ptolemy"},r:{zh:"天文學家、地理學家",en:"Astronomer and geographer"},d:{zh:"亞歷山大城的學者，《天文學大成》中的地心體系影響歐洲與伊斯蘭世界一千四百年，《地理學》以經緯度標註地名。",en:"Scholar of Alexandria whose geocentric Almagest shaped astronomy in Europe and the Islamic world for fourteen centuries; his Geography listed places by latitude and longitude."}},
{id:"marcus-aurelius",y:[121,180],at:["rome","vienna"],n:{zh:"馬可·奧勒留",en:"Marcus Aurelius"},r:{zh:"羅馬皇帝、哲學家",en:"Roman emperor and philosopher"},d:{zh:"“五賢帝”中的最後一位，晚年在多瑙河前線作戰，寫下斯多葛派的《沉思錄》，死於文多博納（今維也納）一帶。",en:"Last of the ‘Five Good Emperors’, who spent his later years fighting on the Danube and wrote the Stoic Meditations; he died at or near Vindobona (Vienna)."}},
{id:"constantine-the-great",y:[272,337],at:["istanbul","trier","york"],n:{zh:"君士坦丁大帝",en:"Constantine the Great"},r:{zh:"羅馬皇帝",en:"Roman emperor"},d:{zh:"在約克被擁立為帝，在米爾維安橋戰勝對手，頒佈寬容基督教的《米蘭敕令》，並將首都遷至君士坦丁堡。",en:"Proclaimed emperor at York, he won at the Milvian Bridge, granted toleration to Christians and moved the capital to Constantinople."}},
{id:"augustine",y:[354,430],at:["carthage","milan","rome"],c:[7.95,36.29],pl:{en:"Thagaste",zh:"塔加斯特"},n:{zh:"奧古斯丁",en:"Augustine of Hippo"},r:{zh:"神學家",en:"Theologian"},d:{zh:"北非出生的神學家，在米蘭皈依基督教，後任希波主教，《懺悔錄》與《上帝之城》深刻影響了西方思想。",en:"North African theologian who converted in Milan and became Bishop of Hippo; his Confessions and City of God shaped Western thought."}},
{id:"hypatia",y:[355,415],ca:1,at:["alexandria"],n:{zh:"希帕提婭",en:"Hypatia"},r:{zh:"哲學家、數學家",en:"Philosopher and mathematician"},d:{zh:"亞歷山大城的新柏拉圖派學者，講授數學與天文學，在城中宗教與政治衝突中被暴徒殺害。",en:"Neoplatonist scholar of Alexandria who taught mathematics and astronomy; she was murdered by a mob amid the city’s religious and political strife."}},
{id:"justinian",y:[482,565],at:["istanbul","ravenna"],n:{zh:"查士丁尼一世",en:"Justinian I"},r:{zh:"拜占庭皇帝",en:"Byzantine emperor"},d:{zh:"編纂《羅馬民法大全》，重建聖索菲亞大教堂，並收復北非與意大利。",en:"Codified Roman law in the Corpus Juris Civilis, rebuilt Hagia Sophia and reconquered North Africa and Italy."}},
// ---- Islamic world ----
{id:"muhammad",y:[570,632],ca:1,at:["mecca","medina"],n:{zh:"穆罕默德",en:"Muhammad"},r:{zh:"伊斯蘭教先知",en:"Prophet of Islam"},d:{zh:"生於麥加，622 年遷往麥地那，此後統一阿拉伯半島大部，是伊斯蘭教的創立者。",en:"Born in Mecca, he moved to Medina in 622 and went on to unite most of Arabia; Muslims regard him as the final prophet of Islam."}},
{id:"harun-al-rashid",y:[763,809],ca:1,at:["baghdad"],n:{zh:"哈倫·拉希德",en:"Harun al-Rashid"},r:{zh:"阿拔斯王朝哈里發",en:"Abbasid caliph"},d:{zh:"阿拔斯王朝鼎盛時期的哈里發，巴格達成為世界性的大都市，《一千零一夜》中多有他的故事。",en:"Abbasid caliph at the height of the dynasty, when Baghdad became a world city; he appears in many tales of the Thousand and One Nights."}},
{id:"al-khwarizmi",y:[780,850],ca:1,at:["baghdad"],n:{zh:"花拉子米",en:"al-Khwarizmi"},r:{zh:"數學家",en:"Mathematician"},d:{zh:"巴格達智慧宮的學者，其著作奠定了代數學，“算法”一詞即源於他的名字，並將印度數字傳入伊斯蘭世界與歐洲。",en:"Scholar of the House of Wisdom in Baghdad whose book founded algebra; the word ‘algorithm’ comes from his name, and he spread Indian numerals to the Islamic world and Europe."}},
{id:"avicenna",y:[980,1037],at:["bukhara","isfahan"],n:{zh:"伊本·西那",en:"Avicenna (Ibn Sina)"},r:{zh:"醫學家、哲學家",en:"Physician and philosopher"},d:{zh:"生於布哈拉附近，所著《醫典》在歐洲與伊斯蘭世界被用作醫學教科書達數百年。",en:"Born near Bukhara, he wrote the Canon of Medicine, used as a medical textbook in the Islamic world and Europe for centuries."}},
{id:"averroes",y:[1126,1198],at:["cordoba","marrakesh"],n:{zh:"伊本·魯世德",en:"Averroes (Ibn Rushd)"},r:{zh:"哲學家",en:"Philosopher"},d:{zh:"科爾多瓦的哲學家和法官，為亞里士多德著作作注，對中世紀歐洲經院哲學影響深遠。",en:"Philosopher and judge of Córdoba whose commentaries on Aristotle deeply influenced medieval European scholasticism."}},
{id:"maimonides",y:[1138,1204],at:["cordoba","fez","cairo"],n:{zh:"邁蒙尼德",en:"Maimonides"},r:{zh:"猶太哲學家、醫生",en:"Jewish philosopher and physician"},d:{zh:"生於科爾多瓦，因迫害遷居非斯、開羅，任薩拉丁宮廷醫生，著有《迷途指津》。",en:"Born in Córdoba, he fled persecution to Fez and Cairo, became court physician to Saladin’s household and wrote the Guide for the Perplexed."}},
{id:"saladin",y:[1137,1193],at:["damascus","cairo","jerusalem"],c:[43.68,34.60],pl:{en:"Tikrit",zh:"提克里特"},n:{zh:"薩拉丁",en:"Saladin"},r:{zh:"埃及與敘利亞蘇丹",en:"Sultan of Egypt and Syria"},d:{zh:"阿尤布王朝的創立者，1187 年在哈丁戰勝十字軍並收復耶路撒冷，葬於大馬士革。",en:"Founder of the Ayyubid dynasty who defeated the Crusaders at Hattin in 1187 and retook Jerusalem; he is buried in Damascus."}},
{id:"saadi",y:[1210,1291],ca:1,at:["shiraz","baghdad"],n:{zh:"薩迪",en:"Saadi"},r:{zh:"詩人",en:"Poet"},d:{zh:"設拉子的波斯詩人，遊歷中東數十年後寫成《果園》與《薔薇園》。",en:"Persian poet of Shiraz who travelled the Middle East for decades and wrote the Bustan and the Gulistan."}},
{id:"rumi",y:[1207,1273],at:["konya"],c:[66.90,36.76],pl:{en:"Balkh",zh:"巴爾赫"},n:{zh:"魯米",en:"Rumi"},r:{zh:"詩人、蘇菲派神秘主義者",en:"Poet and Sufi mystic"},d:{zh:"生於巴爾赫，為躲避蒙古西遷至科尼亞，其波斯語長詩《瑪斯納維》被譽為蘇菲派經典；旋轉舞僧團奉他為祖師。",en:"Born in Balkh, he fled the Mongols to Konya; his Persian Masnavi is a classic of Sufism, and the whirling dervishes trace their order to him."}},
{id:"ibn-battuta",y:[1304,1369],at:["fez","delhi","quanzhou","kilwa"],c:[-5.80,35.77],pl:{en:"Tangier",zh:"丹吉爾"},n:{zh:"伊本·白圖泰",en:"Ibn Battuta"},r:{zh:"旅行家",en:"Traveller"},d:{zh:"出生于丹吉爾，近三十年間遊歷非洲、中東、印度與中國，行程逾十萬公里，回國後在非斯口述遊記。",en:"Born in Tangier, he spent almost thirty years travelling through Africa, the Middle East, India and China, more than 100,000 km, and dictated his travels in Fez."}},
{id:"hafez",y:[1315,1390],ca:1,at:["shiraz"],n:{zh:"哈菲茲",en:"Hafez"},r:{zh:"詩人",en:"Poet"},d:{zh:"設拉子的波斯抒情詩人，其詩集至今在伊朗家家收藏，常被用來占卜。",en:"Lyric poet of Shiraz whose collected poems are still found in almost every Iranian home and are used for divination."}},
{id:"ibn-khaldun",y:[1332,1406],at:["cairo","fez","damascus"],c:[10.17,36.80],pl:{en:"Tunis",zh:"突尼斯"},n:{zh:"伊本·赫勒敦",en:"Ibn Khaldun"},r:{zh:"歷史學家",en:"Historian"},d:{zh:"生於突尼斯，所著《歷史緒論》分析王朝興衰與社會凝聚力，被視為社會學與史學理論的先驅；曾在大馬士革城外會見帖木兒。",en:"Born in Tunis, he wrote the Muqaddimah on the rise and fall of dynasties, a forerunner of sociology; he met Timur outside Damascus."}},
{id:"timur",y:[1336,1405],at:["samarkand","delhi","damascus","ankara"],n:{zh:"帖木兒",en:"Timur (Tamerlane)"},r:{zh:"帖木兒帝國創建者",en:"Founder of the Timurid Empire"},d:{zh:"從河中地區崛起，征戰波斯、印度、敘利亞與安納托利亞，在安卡拉俘獲奧斯曼蘇丹巴耶濟德一世，以撒馬爾罕為都。",en:"Rose in Transoxiana and campaigned through Persia, India, Syria and Anatolia, capturing the Ottoman sultan Bayezid I at Ankara; Samarkand was his capital."}},
{id:"ulugh-beg",y:[1394,1449],at:["samarkand"],n:{zh:"兀魯伯",en:"Ulugh Beg"},r:{zh:"天文學家、君主",en:"Astronomer and ruler"},d:{zh:"帖木兒之孫，在撒馬爾罕修建天文臺，編制的星表是托勒密之後最精確的一部。",en:"Grandson of Timur who built an observatory at Samarkand; his star catalogue was the most accurate since Ptolemy."}},
{id:"mehmed-ii",y:[1432,1481],at:["edirne","istanbul"],n:{zh:"穆罕默德二世",en:"Mehmed II"},r:{zh:"奧斯曼蘇丹",en:"Ottoman sultan"},d:{zh:"生於埃迪爾內，1453 年攻陷君士坦丁堡，終結拜占庭帝國，並將其定為奧斯曼新都。",en:"Born in Edirne, he took Constantinople in 1453, ending the Byzantine Empire, and made it the new Ottoman capital."}},
{id:"suleiman",y:[1494,1566],at:["trabzon","istanbul","budapest","vienna"],n:{zh:"蘇萊曼一世",en:"Suleiman the Magnificent"},r:{zh:"奧斯曼蘇丹",en:"Ottoman sultan"},d:{zh:"生於特拉布宗，在位期間奧斯曼帝國達到鼎盛，攻取貝爾格萊德與布達，圍攻維也納，並編訂法典。",en:"Born in Trabzon, he led the Ottoman Empire at its height, took Belgrade and Buda, besieged Vienna and reformed the law."}},
{id:"shah-abbas",y:[1571,1629],at:["isfahan"],n:{zh:"阿拔斯一世",en:"Shah Abbas I"},r:{zh:"薩法維王朝君主",en:"Safavid shah"},d:{zh:"薩法維王朝最傑出的君主，奪回被奧斯曼佔領的領土，遷都伊斯法罕並營建伊瑪目廣場。",en:"The greatest Safavid ruler, who won back land from the Ottomans, moved the capital to Isfahan and built its great square."}},
{id:"muhammad-ali-pasha",y:[1769,1849],at:["cairo","alexandria"],c:[24.41,40.94],pl:{en:"Kavala",zh:"卡瓦拉"},n:{zh:"穆罕默德·阿里",en:"Muhammad Ali Pasha"},r:{zh:"埃及總督",en:"Ruler of Egypt"},d:{zh:"奧斯曼帝國的埃及總督，推行軍事和經濟改革，被視為現代埃及的奠基者。",en:"Ottoman governor of Egypt whose military and economic reforms made him the founder of modern Egypt."}},
{id:"ataturk",y:[1881,1938],at:["thessaloniki","ankara","istanbul"],n:{zh:"穆斯塔法·凱末爾·阿塔圖爾克",en:"Mustafa Kemal Atatürk"},r:{zh:"土耳其共和國創建者",en:"Founder of the Republic of Turkey"},d:{zh:"生於薩洛尼卡，加里波利戰役中成名，領導獨立戰爭後建立土耳其共和國，定都安卡拉並推行世俗化改革。",en:"Born in Salonica, he made his name at Gallipoli, led the War of Independence and founded the Turkish Republic with Ankara as capital, introducing secular reforms."}},
{id:"nasser",y:[1918,1970],at:["alexandria","cairo"],n:{zh:"納賽爾",en:"Gamal Abdel Nasser"},r:{zh:"埃及總統",en:"President of Egypt"},d:{zh:"1952 年自由軍官革命的領導者，1956 年將蘇伊士運河收歸國有，是阿拉伯民族主義的代表人物。",en:"Leader of the Free Officers’ revolution of 1952 who nationalised the Suez Canal in 1956 and became the figurehead of Arab nationalism."}},
// ---- Medieval & early modern Europe ----
{id:"charlemagne",y:[742,814],ca:1,at:["aachen","rome"],n:{zh:"查理曼",en:"Charlemagne"},r:{zh:"法蘭克國王、皇帝",en:"King of the Franks and emperor"},d:{zh:"統一西歐大部，800 年聖誕節在羅馬由教皇加冕為皇帝，以亞琛為都推動“加洛林文藝復興”。",en:"United most of western Europe and was crowned emperor by the pope in Rome on Christmas Day 800; from Aachen he fostered the Carolingian Renaissance."}},
{id:"alfred-the-great",y:[849,899],at:["london","york"],c:[-1.31,51.06],pl:{en:"Winchester",zh:"溫切斯特"},n:{zh:"阿爾弗雷德大王",en:"Alfred the Great"},r:{zh:"威塞克斯國王",en:"King of Wessex"},d:{zh:"抵禦維京大軍，重建倫敦並修築設防城鎮，推動以古英語翻譯典籍。",en:"Held off the Viking Great Army, refounded London, built a network of fortified towns and promoted translation into Old English."}},
{id:"william-the-conqueror",y:[1028,1087],at:["london","york"],c:[-0.42,48.89],pl:{en:"Falaise",zh:"法萊斯"},n:{zh:"征服者威廉",en:"William the Conqueror"},r:{zh:"英格蘭國王",en:"King of England"},d:{zh:"諾曼底公爵，1066 年在黑斯廷斯戰役中獲勝，成為英格蘭國王，下令編纂《末日審判書》。",en:"Duke of Normandy who won the Battle of Hastings in 1066, became King of England and ordered the Domesday survey."}},
{id:"el-cid",y:[1043,1099],ca:1,at:["valencia","toledo"],n:{zh:"熙德",en:"El Cid"},r:{zh:"卡斯蒂利亞騎士",en:"Castilian knight"},d:{zh:"羅德里戈·迪亞斯，卡斯蒂利亞貴族，曾為基督徒和穆斯林君主效力，1094 年攻取巴倫西亞並統治至死。",en:"Rodrigo Díaz, a Castilian noble who served both Christian and Muslim rulers; he took Valencia in 1094 and ruled it until his death."}},
{id:"frederick-ii",y:[1194,1250],at:["palermo","naples"],n:{zh:"腓特烈二世",en:"Frederick II"},r:{zh:"神聖羅馬皇帝、西西里國王",en:"Holy Roman Emperor and King of Sicily"},d:{zh:"在巴勒莫長大，通曉多種語言，創辦那不勒斯大學，以談判方式收回耶路撒冷，與教皇長期對立。",en:"Raised in Palermo and fluent in several languages, he founded the University of Naples, regained Jerusalem by treaty and fought a long struggle with the papacy."}},
{id:"thomas-aquinas",y:[1225,1274],at:["naples","paris"],n:{zh:"托馬斯·阿奎那",en:"Thomas Aquinas"},r:{zh:"神學家",en:"Theologian"},d:{zh:"多明我會修士，在巴黎與那不勒斯講學，《神學大全》將亞里士多德哲學與基督教神學結合。",en:"Dominican friar who taught in Paris and Naples; his Summa Theologiae joined Aristotle’s philosophy to Christian theology."}},
{id:"marco-polo",y:[1254,1324],at:["venice","beijing","quanzhou","genoa"],n:{zh:"馬可·波羅",en:"Marco Polo"},r:{zh:"商人、旅行家",en:"Merchant and traveller"},d:{zh:"威尼斯商人，隨父輩經絲綢之路到達元朝，在忽必烈治下生活約十七年，其遊記讓歐洲認識了東方。",en:"Venetian merchant who travelled the Silk Road to Yuan China and spent some seventeen years under Kublai Khan; his book introduced Asia to Europe."}},
{id:"dante",y:[1265,1321],at:["florence","ravenna"],n:{zh:"但丁",en:"Dante Alighieri"},r:{zh:"詩人",en:"Poet"},d:{zh:"佛羅倫薩詩人，因政爭被放逐，在流亡中寫成以托斯卡納方言創作的《神曲》，卒於拉文納。",en:"Florentine poet exiled in a political feud, who wrote the Divine Comedy in Tuscan in exile and died in Ravenna."}},
{id:"giotto",y:[1267,1337],ca:1,at:["florence"],n:{zh:"喬托",en:"Giotto"},r:{zh:"畫家、建築師",en:"Painter and architect"},d:{zh:"以寫實的人物與空間感打破拜占庭畫風，被視為文藝復興繪畫的先驅，設計了佛羅倫薩大教堂鐘樓。",en:"Broke with the Byzantine style through lifelike figures and space, a forerunner of Renaissance painting; he designed the bell tower of Florence Cathedral."}},
{id:"petrarch",y:[1304,1374],at:["avignon","florence"],c:[11.88,43.46],pl:{en:"Arezzo",zh:"阿雷佐"},n:{zh:"彼特拉克",en:"Petrarch"},r:{zh:"詩人、人文主義者",en:"Poet and humanist"},d:{zh:"在阿維尼翁教廷長大，以獻給勞拉的十四行詩聞名，蒐集古典手稿，被稱為“人文主義之父”。",en:"Grew up at the papal court in Avignon; famous for his sonnets to Laura and his search for classical manuscripts, he is called the father of humanism."}},
{id:"jan-hus",y:[1372,1415],ca:1,at:["prague"],n:{zh:"揚·胡斯",en:"Jan Hus"},r:{zh:"宗教改革家",en:"Church reformer"},d:{zh:"布拉格大學校長，批評教會腐敗，在康斯坦茨公會議上被判為異端並處以火刑，引發胡斯戰爭。",en:"Rector of Prague University who attacked church corruption; condemned as a heretic at the Council of Constance and burned, his death set off the Hussite Wars."}},
{id:"joan-of-arc",y:[1412,1431],ca:1,at:["reims","paris"],c:[5.67,48.44],pl:{en:"Domrémy",zh:"棟雷米"},n:{zh:"聖女貞德",en:"Joan of Arc"},r:{zh:"法國民族英雄",en:"French national heroine"},d:{zh:"農家少女，百年戰爭中解奧爾良之圍，護送查理七世在蘭斯加冕，後被英國人以異端罪名處以火刑。",en:"Peasant girl who raised the siege of Orléans in the Hundred Years’ War and brought Charles VII to be crowned at Reims; the English burned her as a heretic."}},
{id:"gutenberg",y:[1400,1468],ca:1,at:["strasbourg"],c:[8.27,50.00],pl:{en:"Mainz",zh:"美因茨"},n:{zh:"古騰堡",en:"Johannes Gutenberg"},r:{zh:"印刷術發明者",en:"Inventor of printing"},d:{zh:"在美因茨發明金屬活字印刷機，印製了《古騰堡聖經》，此前曾在斯特拉斯堡試驗。",en:"Developed printing with movable metal type in Mainz and printed the Gutenberg Bible, after early experiments in Strasbourg."}},
{id:"lorenzo-de-medici",y:[1449,1492],at:["florence"],n:{zh:"洛倫佐·德·美第奇",en:"Lorenzo de’ Medici"},r:{zh:"佛羅倫薩統治者",en:"Ruler of Florence"},d:{zh:"人稱“偉大的洛倫佐”，佛羅倫薩的實際統治者，資助波提切利、米開朗琪羅等藝術家。",en:"Known as Lorenzo the Magnificent, the de facto ruler of Florence and patron of Botticelli, Michelangelo and others."}},
{id:"leonardo",y:[1452,1519],at:["florence","milan"],c:[10.92,43.79],pl:{en:"Vinci",zh:"芬奇鎮"},n:{zh:"列奧納多·達·芬奇",en:"Leonardo da Vinci"},r:{zh:"畫家、發明家",en:"Painter and inventor"},d:{zh:"文藝復興“全才”，作品有《蒙娜麗莎》與米蘭的《最後的晚餐》，筆記涉及解剖、工程與飛行。",en:"Renaissance polymath who painted the Mona Lisa and the Last Supper in Milan and filled notebooks with anatomy, engineering and flying machines."}},
{id:"columbus",y:[1451,1506],at:["genoa","seville","santodomingo"],n:{zh:"克里斯托弗·哥倫布",en:"Christopher Columbus"},r:{zh:"航海家",en:"Navigator"},d:{zh:"生於熱那亞，受西班牙雙王資助於 1492 年橫渡大西洋抵達加勒比海，開啟歐洲對美洲的殖民。",en:"Genoese navigator who crossed the Atlantic for the Spanish monarchs in 1492 and reached the Caribbean, beginning European colonisation of the Americas."}},
{id:"henry-the-navigator",y:[1394,1460],at:["porto","lisbon"],n:{zh:"航海家恩裡克",en:"Henry the Navigator"},r:{zh:"葡萄牙王子",en:"Portuguese prince"},d:{zh:"若昂一世之子，資助沿非洲西岸南下的航海探險，為葡萄牙海上帝國奠定基礎。",en:"Son of John I who sponsored voyages down the west coast of Africa, laying the foundations of Portugal’s sea empire."}},
{id:"vasco-da-gama",y:[1469,1524],ca:1,at:["lisbon","calicut","goa"],n:{zh:"瓦斯科·達·伽馬",en:"Vasco da Gama"},r:{zh:"航海家",en:"Navigator"},d:{zh:"1497 年從里斯本出發繞過好望角，1498 年抵達卡利卡特，開闢歐洲直達印度的航路；卒於印度。",en:"Sailed from Lisbon in 1497 around the Cape of Good Hope and reached Calicut in 1498, opening the sea route from Europe to India; he died in India."}},
{id:"machiavelli",y:[1469,1527],at:["florence"],n:{zh:"馬基雅維利",en:"Niccolò Machiavelli"},r:{zh:"政治思想家",en:"Political thinker"},d:{zh:"佛羅倫薩共和國的外交官，美第奇家族復辟後寫成《君主論》，開創了現實主義政治學。",en:"Diplomat of the Florentine Republic who, after the Medici returned, wrote The Prince and founded realist political thought."}},
{id:"copernicus",y:[1473,1543],at:["krakow","gdansk"],c:[18.60,53.01],pl:{en:"Toruń",zh:"托倫"},n:{zh:"尼古拉·哥白尼",en:"Nicolaus Copernicus"},r:{zh:"天文學家",en:"Astronomer"},d:{zh:"在克拉科夫求學，臨終前出版《天體運行論》，提出日心說。",en:"Studied in Kraków and, as he was dying, published On the Revolutions of the Heavenly Spheres, setting the Sun at the centre."}},
{id:"michelangelo",y:[1475,1564],at:["florence","rome"],n:{zh:"米開朗琪羅",en:"Michelangelo"},r:{zh:"雕塑家、畫家、建築師",en:"Sculptor, painter and architect"},d:{zh:"創作了佛羅倫薩的《大衛》、西斯廷禮拜堂天頂畫，並主持設計聖彼得大教堂穹頂。",en:"Carved the David in Florence, painted the Sistine Chapel ceiling and designed the dome of St Peter’s."}},
{id:"magellan",y:[1480,1521],ca:1,at:["seville","lisbon","manila"],n:{zh:"費迪南德·麥哲倫",en:"Ferdinand Magellan"},r:{zh:"航海家",en:"Navigator"},d:{zh:"葡萄牙航海家，為西班牙率船隊從塞維利亞出發，穿越麥哲倫海峽橫渡太平洋，在菲律賓戰死；船隊完成首次環球航行。",en:"Portuguese navigator who led a Spanish fleet from Seville through the strait that bears his name and across the Pacific; he was killed in the Philippines, but his ship completed the first circumnavigation."}},
{id:"luther",y:[1483,1546],at:[],c:[12.65,51.87],pl:{en:"Wittenberg",zh:"維滕貝格"},n:{zh:"馬丁·路德",en:"Martin Luther"},r:{zh:"宗教改革家",en:"Reformer"},d:{zh:"維滕貝格大學教授，1517 年發表《九十五條論綱》，引發宗教改革，並將《聖經》譯成德語。",en:"Professor at Wittenberg who published the Ninety-five Theses in 1517, setting off the Reformation, and translated the Bible into German."}},
{id:"raphael",y:[1483,1520],at:["rome","florence"],c:[12.64,43.73],pl:{en:"Urbino",zh:"烏爾比諾"},n:{zh:"拉斐爾",en:"Raphael"},r:{zh:"畫家",en:"Painter"},d:{zh:"盛期文藝復興畫家，為梵蒂岡繪製《雅典學院》等壁畫，三十七歲卒於羅馬。",en:"High Renaissance painter of the School of Athens and other frescoes in the Vatican; he died in Rome aged thirty-seven."}},
{id:"durer",y:[1471,1528],at:["nuremberg","venice"],n:{zh:"阿爾布雷希特·丟勒",en:"Albrecht Dürer"},r:{zh:"畫家、版畫家",en:"Painter and printmaker"},d:{zh:"紐倫堡畫家，兩度遊歷意大利，把文藝復興藝術帶到北方，木刻與銅版畫聞名歐洲。",en:"Nuremberg artist who twice travelled to Italy and brought the Renaissance north; his woodcuts and engravings were famous across Europe."}},
{id:"charles-v",y:[1500,1558],at:["brussels","toledo","bologna"],c:[3.72,51.05],pl:{en:"Ghent",zh:"根特"},n:{zh:"查理五世",en:"Charles V"},r:{zh:"神聖羅馬皇帝、西班牙國王",en:"Holy Roman Emperor and King of Spain"},d:{zh:"生於根特，繼承哈布斯堡、勃艮第與西班牙領地，統治“日不落”帝國，1556 年在布魯塞爾退位。",en:"Born in Ghent, he inherited the Habsburg, Burgundian and Spanish lands, ruled an empire ‘on which the sun never set’ and abdicated in Brussels in 1556."}},
{id:"calvin",y:[1509,1564],at:["geneva","paris"],c:[3.00,49.58],pl:{en:"Noyon",zh:"努瓦永"},n:{zh:"約翰·加爾文",en:"John Calvin"},r:{zh:"宗教改革家",en:"Reformer"},d:{zh:"法國神學家，在日內瓦推行宗教改革，所著《基督教要義》影響了歐洲與北美的新教。",en:"French theologian who led the Reformation in Geneva; his Institutes shaped Protestantism in Europe and North America."}},
{id:"elizabeth-i",y:[1533,1603],at:["london"],n:{zh:"伊麗莎白一世",en:"Elizabeth I"},r:{zh:"英格蘭女王",en:"Queen of England"},d:{zh:"都鐸王朝末代君主，確立英格蘭國教，1588 年擊敗西班牙無敵艦隊，在位期間戲劇文學繁榮。",en:"Last Tudor monarch, who settled the Church of England, saw off the Spanish Armada in 1588 and reigned over a golden age of drama."}},
{id:"philip-ii",y:[1527,1598],at:["madrid","toledo","lisbon"],c:[-4.72,41.65],pl:{en:"Valladolid",zh:"巴利亞多利德"},n:{zh:"腓力二世",en:"Philip II"},r:{zh:"西班牙國王",en:"King of Spain"},d:{zh:"定都馬德里，1580 年兼任葡萄牙國王，統治橫跨美洲與亞洲的帝國，菲律賓即以他命名。",en:"Settled the court in Madrid, became King of Portugal in 1580 and ruled an empire spanning the Americas and Asia; the Philippines are named after him."}},
{id:"cervantes",y:[1547,1616],at:["madrid","seville"],c:[-3.36,40.48],pl:{en:"Alcalá de Henares",zh:"阿爾卡拉"},n:{zh:"塞萬提斯",en:"Miguel de Cervantes"},r:{zh:"作家",en:"Writer"},d:{zh:"曾參加勒班陀海戰並被阿爾及爾海盜俘虜五年，晚年寫成《堂吉訶德》，被視為第一部現代小說。",en:"Fought at Lepanto and spent five years as a captive in Algiers; late in life he wrote Don Quixote, often called the first modern novel."}},
{id:"shakespeare",y:[1564,1616],at:["london"],c:[-1.71,52.19],pl:{en:"Stratford-upon-Avon",zh:"斯特拉特福"},n:{zh:"威廉·莎士比亞",en:"William Shakespeare"},r:{zh:"劇作家、詩人",en:"Playwright and poet"},d:{zh:"在倫敦環球劇場寫作與演出，留下《哈姆雷特》《李爾王》等近四十部劇作。",en:"Wrote and acted for the Globe in London, leaving nearly forty plays including Hamlet and King Lear."}},
{id:"galileo",y:[1564,1642],at:["florence","rome"],c:[10.40,43.72],pl:{en:"Pisa",zh:"比薩"},n:{zh:"伽利略",en:"Galileo Galilei"},r:{zh:"科學家",en:"Scientist"},d:{zh:"用望遠鏡發現木星衛星與金星相位，支持日心說，1633 年在羅馬受宗教裁判所審判，餘生軟禁於佛羅倫薩附近。",en:"Used the telescope to find Jupiter’s moons and the phases of Venus in support of Copernicus; tried by the Inquisition in Rome in 1633, he spent his last years under house arrest near Florence."}},
{id:"rubens",y:[1577,1640],at:["antwerp"],n:{zh:"彼得·保羅·魯本斯",en:"Peter Paul Rubens"},r:{zh:"畫家",en:"Painter"},d:{zh:"安特衛普的巴洛克畫家與外交官，工作室為歐洲各國宮廷繪製大型作品。",en:"Baroque painter and diplomat of Antwerp whose workshop produced great canvases for the courts of Europe."}},
{id:"descartes",y:[1596,1650],at:["amsterdam","stockholm","paris"],c:[0.70,46.97],pl:{en:"La Haye en Touraine",zh:"拉艾"},n:{zh:"勒內·笛卡爾",en:"René Descartes"},r:{zh:"哲學家、數學家",en:"Philosopher and mathematician"},d:{zh:"“我思故我在”，長期旅居荷蘭，創立解析幾何，應克里斯蒂娜女王之邀赴斯德哥爾摩，次年病逝。",en:"‘I think, therefore I am.’ He lived for years in the Dutch Republic, created analytic geometry and died in Stockholm after joining Queen Christina’s court."}},
{id:"rembrandt",y:[1606,1669],at:["amsterdam"],c:[4.49,52.16],pl:{en:"Leiden",zh:"萊頓"},n:{zh:"倫勃朗",en:"Rembrandt"},r:{zh:"畫家",en:"Painter"},d:{zh:"荷蘭黃金時代最偉大的畫家，代表作《夜巡》，晚年在阿姆斯特丹破產。",en:"The greatest painter of the Dutch Golden Age, known for The Night Watch; he went bankrupt in Amsterdam late in life."}},
{id:"spinoza",y:[1632,1677],at:["amsterdam"],n:{zh:"巴魯赫·斯賓諾莎",en:"Baruch Spinoza"},r:{zh:"哲學家",en:"Philosopher"},d:{zh:"阿姆斯特丹的猶太裔哲學家，被猶太社群開除教籍，以磨鏡片為生，著有《倫理學》。",en:"Philosopher from Amsterdam’s Jewish community, which expelled him; he ground lenses for a living and wrote the Ethics."}},
{id:"louis-xiv",y:[1638,1715],at:["paris"],c:[2.09,48.90],pl:{en:"Saint-Germain-en-Laye",zh:"聖日耳曼昂萊"},n:{zh:"路易十四",en:"Louis XIV"},r:{zh:"法國國王",en:"King of France"},d:{zh:"“太陽王”，在位七十二年，修建凡爾賽宮，是歐洲絕對君主制的典型。",en:"The ‘Sun King’, who reigned for seventy-two years, built Versailles and became the model of absolute monarchy."}},
{id:"newton",y:[1643,1727],at:["london"],c:[0.12,52.21],pl:{en:"Cambridge",zh:"劍橋"},n:{zh:"艾薩克·牛頓",en:"Isaac Newton"},r:{zh:"科學家",en:"Scientist"},d:{zh:"劍橋學者，《自然哲學的數學原理》提出萬有引力與運動定律，後任倫敦皇家鑄幣廠廠長。",en:"Cambridge scholar whose Principia set out the laws of motion and universal gravitation; he later ran the Royal Mint in London."}},
{id:"peter-the-great",y:[1672,1725],at:["moscow","stpete"],n:{zh:"彼得大帝",en:"Peter the Great"},r:{zh:"俄國沙皇",en:"Tsar of Russia"},d:{zh:"親赴西歐學習，推行西化改革，擊敗瑞典取得波羅的海出海口，建聖彼得堡並遷都。",en:"Toured western Europe, forced through westernising reforms, defeated Sweden for access to the Baltic and built St Petersburg as his new capital."}},
{id:"bach",y:[1685,1750],at:[],c:[12.37,51.34],pl:{en:"Leipzig",zh:"萊比錫"},n:{zh:"約翰·塞巴斯蒂安·巴赫",en:"Johann Sebastian Bach"},r:{zh:"作曲家",en:"Composer"},d:{zh:"巴洛克音樂的集大成者，晚年任萊比錫聖托馬斯教堂樂長，作品有《馬太受難曲》和《平均律鋼琴曲集》。",en:"The culmination of Baroque music, cantor of St Thomas’s in Leipzig in his last decades; his works include the St Matthew Passion and the Well-Tempered Clavier."}},
{id:"voltaire",y:[1694,1778],at:["paris","geneva"],n:{zh:"伏爾泰",en:"Voltaire"},r:{zh:"啟蒙思想家",en:"Enlightenment writer"},d:{zh:"以諷刺抨擊教會與專制，倡導宗教寬容，晚年住在日內瓦附近的費內。",en:"Satirist who attacked the Church and arbitrary power and championed religious tolerance; he spent his later years at Ferney near Geneva."}},
{id:"rousseau",y:[1712,1778],at:["geneva","paris"],n:{zh:"讓-雅克·盧梭",en:"Jean-Jacques Rousseau"},r:{zh:"思想家",en:"Philosopher"},d:{zh:"生於日內瓦，《社會契約論》提出人民主權學說，深刻影響了法國大革命。",en:"Born in Geneva, he wrote The Social Contract on popular sovereignty, a major influence on the French Revolution."}},
{id:"kant",y:[1724,1804],at:["konigsberg"],n:{zh:"伊曼努爾·康德",en:"Immanuel Kant"},r:{zh:"哲學家",en:"Philosopher"},d:{zh:"終生生活在柯尼斯堡，著有《純粹理性批判》，是啟蒙運動最重要的哲學家之一。",en:"Spent his whole life in Königsberg and wrote the Critique of Pure Reason, making him one of the central philosophers of the Enlightenment."}},
{id:"catherine-the-great",y:[1729,1796],at:["stpete","odesa","sevastopol"],c:[14.55,53.43],pl:{en:"Stettin",zh:"什切青"},n:{zh:"葉卡捷琳娜二世",en:"Catherine the Great"},r:{zh:"俄國女皇",en:"Empress of Russia"},d:{zh:"德意志公主出身，推翻丈夫登基，兼併克里米亞、參與瓜分波蘭，下令建立敖德薩。",en:"A German princess who overthrew her husband to take the throne, annexed Crimea, joined the partitions of Poland and ordered Odesa founded."}},
{id:"goethe",y:[1749,1832],at:[],c:[8.68,50.11],pl:{en:"Frankfurt and Weimar",zh:"法蘭克福、魏瑪"},n:{zh:"歌德",en:"Johann Wolfgang von Goethe"},r:{zh:"作家",en:"Writer"},d:{zh:"生於法蘭克福，在魏瑪宮廷任職數十年，代表作《少年維特之煩惱》與《浮士德》。",en:"Born in Frankfurt, he served the court of Weimar for decades; his works include The Sorrows of Young Werther and Faust."}},
{id:"mozart",y:[1756,1791],at:["salzburg","vienna","prague"],n:{zh:"沃爾夫岡·阿瑪多伊斯·莫扎特",en:"Wolfgang Amadeus Mozart"},r:{zh:"作曲家",en:"Composer"},d:{zh:"薩爾茨堡出生的神童，後定居維也納，創作歌劇《費加羅的婚禮》《唐璜》（首演於布拉格）等，三十五歲去世。",en:"Child prodigy from Salzburg who settled in Vienna and wrote operas including The Marriage of Figaro and Don Giovanni, first staged in Prague; he died at thirty-five."}},
{id:"napoleon",y:[1769,1821],at:["paris","moscow"],c:[8.74,41.92],pl:{en:"Ajaccio",zh:"阿雅克肖"},n:{zh:"拿破崙·波拿巴",en:"Napoleon Bonaparte"},r:{zh:"法國皇帝",en:"Emperor of the French"},d:{zh:"生於科西嘉，大革命中崛起，1804 年稱帝，頒佈《拿破崙法典》，征服歐洲大部，滑鐵盧戰敗後被流放聖赫勒拿島。",en:"Corsican who rose in the Revolution, crowned himself emperor in 1804, issued the Napoleonic Code and conquered much of Europe; after Waterloo he was exiled to St Helena."}},
{id:"beethoven",y:[1770,1827],at:["vienna"],c:[7.10,50.73],pl:{en:"Bonn",zh:"波恩"},n:{zh:"路德維希·凡·貝多芬",en:"Ludwig van Beethoven"},r:{zh:"作曲家",en:"Composer"},d:{zh:"生於波恩，在維也納度過創作生涯，耳聾後仍寫出《第九交響曲》，連接古典與浪漫主義。",en:"Born in Bonn, he worked in Vienna and, though deaf, composed the Ninth Symphony, bridging the Classical and Romantic eras."}},
{id:"chopin",y:[1810,1849],at:["warsaw","paris"],n:{zh:"弗雷德里克·肖邦",en:"Frédéric Chopin"},r:{zh:"作曲家、鋼琴家",en:"Composer and pianist"},d:{zh:"在華沙長大，1830 年起旅居巴黎，鋼琴作品融入波蘭民族音樂，心臟被送回華沙安葬。",en:"Raised in Warsaw, he lived in Paris from 1830; his piano music draws on Polish dances, and his heart was returned to Warsaw."}},
{id:"garibaldi",y:[1807,1882],at:["palermo","naples","rome"],c:[7.27,43.70],pl:{en:"Nice",zh:"尼斯"},n:{zh:"朱塞佩·加里波第",en:"Giuseppe Garibaldi"},r:{zh:"意大利統一運動領袖",en:"Leader of Italian unification"},d:{zh:"率“千人軍”遠征西西里與那不勒斯，推翻兩西西里王國，促成意大利統一。",en:"Led the Thousand to conquer Sicily and Naples, toppling the Kingdom of the Two Sicilies and helping to unite Italy."}},
{id:"darwin",y:[1809,1882],at:["london"],c:[-2.75,52.71],pl:{en:"Shrewsbury",zh:"什魯斯伯裡"},n:{zh:"查爾斯·達爾文",en:"Charles Darwin"},r:{zh:"博物學家",en:"Naturalist"},d:{zh:"隨“小獵犬號”環球考察，1859 年出版《物種起源》，提出自然選擇學說。",en:"Sailed round the world on the Beagle and in 1859 published On the Origin of Species, setting out evolution by natural selection."}},
{id:"queen-victoria",y:[1819,1901],at:["london"],n:{zh:"維多利亞女王",en:"Queen Victoria"},r:{zh:"英國女王",en:"Queen of the United Kingdom"},d:{zh:"在位六十三年，英國工業與殖民帝國達到頂峰，1876 年加冕印度女皇。",en:"Reigned for sixty-three years over the height of Britain’s industrial and imperial power, and became Empress of India in 1876."}},
{id:"victor-hugo",y:[1802,1885],at:["paris"],c:[6.02,47.24],pl:{en:"Besançon",zh:"貝桑松"},n:{zh:"維克多·雨果",en:"Victor Hugo"},r:{zh:"作家",en:"Writer"},d:{zh:"法國浪漫主義文學領袖，著有《巴黎聖母院》《悲慘世界》，因反對拿破崙三世流亡近二十年。",en:"Leader of French Romanticism, author of Notre-Dame de Paris and Les Misérables; he spent nearly twenty years in exile for opposing Napoleon III."}},
{id:"bismarck",y:[1815,1898],at:["berlin"],n:{zh:"奧托·馮·俾斯麥",en:"Otto von Bismarck"},r:{zh:"德意志帝國首相",en:"Chancellor of Germany"},d:{zh:"普魯士首相，通過三次戰爭實現德意志統一，1871 年任德意志帝國首相。",en:"Prussian minister-president who unified Germany through three wars and became the first chancellor of the German Empire in 1871."}},
{id:"marx",y:[1818,1883],at:["trier","london","paris"],n:{zh:"卡爾·馬克思",en:"Karl Marx"},r:{zh:"思想家",en:"Philosopher and economist"},d:{zh:"生於特里爾，與恩格斯合著《共產黨宣言》，流亡倫敦期間寫成《資本論》。",en:"Born in Trier, he wrote The Communist Manifesto with Engels and, in exile in London, Capital."}},
{id:"dostoevsky",y:[1821,1881],at:["moscow","stpete"],n:{zh:"陀思妥耶夫斯基",en:"Fyodor Dostoevsky"},r:{zh:"作家",en:"Writer"},d:{zh:"生於莫斯科，曾被流放西伯利亞，在聖彼得堡寫成《罪與罰》《卡拉馬佐夫兄弟》。",en:"Born in Moscow and exiled to Siberia, he wrote Crime and Punishment and The Brothers Karamazov in St Petersburg."}},
{id:"tolstoy",y:[1828,1910],at:["moscow"],c:[37.53,54.08],pl:{en:"Yasnaya Polyana",zh:"亞斯納亞·波利亞納"},n:{zh:"列夫·托爾斯泰",en:"Leo Tolstoy"},r:{zh:"作家",en:"Writer"},d:{zh:"俄國作家，曾參加克里米亞戰爭中的塞瓦斯托波爾保衛戰，著有《戰爭與和平》《安娜·卡列尼娜》。",en:"Russian novelist who fought at Sevastopol in the Crimean War and wrote War and Peace and Anna Karenina."}},
{id:"tchaikovsky",y:[1840,1893],at:["stpete","moscow"],c:[52.30,58.06],pl:{en:"Votkinsk",zh:"沃特金斯克"},n:{zh:"柴可夫斯基",en:"Pyotr Ilyich Tchaikovsky"},r:{zh:"作曲家",en:"Composer"},d:{zh:"俄國作曲家，作品有芭蕾舞劇《天鵝湖》《胡桃夾子》及《第六交響曲》。",en:"Russian composer of the ballets Swan Lake and The Nutcracker and of the Sixth Symphony."}},
{id:"marie-curie",y:[1867,1934],at:["warsaw","paris"],n:{zh:"瑪麗·居里",en:"Marie Curie"},r:{zh:"物理學家、化學家",en:"Physicist and chemist"},d:{zh:"生於華沙，在巴黎研究放射性，發現釙和鐳，是第一位兩次獲得諾貝爾獎的人。",en:"Born in Warsaw, she studied radioactivity in Paris, discovered polonium and radium and was the first person to win two Nobel Prizes."}},
{id:"freud",y:[1856,1939],at:["vienna","london"],c:[18.15,49.59],pl:{en:"Příbor",zh:"普日博爾"},n:{zh:"西格蒙德·弗洛伊德",en:"Sigmund Freud"},r:{zh:"精神分析學創始人",en:"Founder of psychoanalysis"},d:{zh:"在維也納行醫數十年，創立精神分析學，1938 年為躲避納粹流亡倫敦。",en:"Practised in Vienna for decades and founded psychoanalysis; he fled the Nazis to London in 1938."}},
{id:"lenin",y:[1870,1924],at:["kazan","stpete","moscow"],c:[48.40,54.32],pl:{en:"Simbirsk",zh:"辛比爾斯克"},n:{zh:"列寧",en:"Vladimir Lenin"},r:{zh:"布爾什維克領袖",en:"Bolshevik leader"},d:{zh:"在喀山求學時投身革命，領導 1917 年十月革命，建立蘇維埃政權並遷都莫斯科。",en:"Turned to revolution as a student in Kazan, led the October Revolution of 1917 and founded the Soviet state with its capital in Moscow."}},
{id:"churchill",y:[1874,1965],at:["london"],c:[-1.36,51.84],pl:{en:"Blenheim Palace",zh:"布倫海姆宮"},n:{zh:"溫斯頓·丘吉爾",en:"Winston Churchill"},r:{zh:"英國首相",en:"British prime minister"},d:{zh:"第二次世界大戰期間領導英國抵抗納粹德國，1953 年獲諾貝爾文學獎。",en:"Led Britain against Nazi Germany in the Second World War and won the Nobel Prize in Literature in 1953."}},
{id:"stalin",y:[1878,1953],at:["tbilisi","moscow"],c:[44.11,41.98],pl:{en:"Gori",zh:"哥里"},n:{zh:"約瑟夫·斯大林",en:"Joseph Stalin"},r:{zh:"蘇聯領導人",en:"Soviet leader"},d:{zh:"生於格魯吉亞，列寧死後掌握蘇聯最高權力，推行集體化與工業化，發動大清洗，領導蘇聯贏得衛國戰爭。",en:"Georgian who took control of the Soviet Union after Lenin, forced collectivisation and industrialisation, ran the Great Purge and led the country to victory in the Second World War."}},
{id:"einstein",y:[1879,1955],at:["berlin","prague"],c:[9.99,48.40],pl:{en:"Ulm",zh:"烏爾姆"},n:{zh:"阿爾伯特·愛因斯坦",en:"Albert Einstein"},r:{zh:"物理學家",en:"Physicist"},d:{zh:"提出狹義與廣義相對論，曾在布拉格與柏林任教，1933 年移居美國。",en:"Developed the special and general theories of relativity, taught in Prague and Berlin, and moved to the United States in 1933."}},
{id:"kafka",y:[1883,1924],at:["prague"],n:{zh:"弗朗茨·卡夫卡",en:"Franz Kafka"},r:{zh:"作家",en:"Writer"},d:{zh:"布拉格的德語猶太作家，生前在保險公司任職，《變形記》《審判》在他死後才廣為人知。",en:"German-speaking Jewish writer of Prague who worked for an insurance office; The Metamorphosis and The Trial became famous only after his death."}},
{id:"de-gaulle",y:[1890,1970],at:["paris","london"],c:[3.06,50.63],pl:{en:"Lille",zh:"里爾"},n:{zh:"夏爾·戴高樂",en:"Charles de Gaulle"},r:{zh:"法國總統",en:"President of France"},d:{zh:"1940 年在倫敦號召法國人繼續抵抗，領導“自由法國”，1958 年創建第五共和國。",en:"Called on the French to fight on from London in 1940, led Free France and founded the Fifth Republic in 1958."}},
// ---- China ----
{id:"confucius",y:[-551,-479],at:["qufu"],n:{zh:"孔子",en:"Confucius"},r:{zh:"思想家、教育家",en:"Philosopher and teacher"},d:{zh:"春秋時魯國人，周遊列國宣揚仁政與禮制，弟子編成的《論語》成為兩千多年中國思想的核心。",en:"Thinker from the state of Lu who travelled the states urging rule by virtue and ritual; the Analects compiled by his disciples became the core of Chinese thought for two thousand years."}},
{id:"qin-shi-huang",y:[-259,-210],at:["xian"],c:[114.49,36.61],pl:{en:"Handan",zh:"邯鄲"},n:{zh:"秦始皇",en:"Qin Shi Huang"},r:{zh:"中國第一位皇帝",en:"First Emperor of China"},d:{zh:"生於趙國邯鄲，公元前 221 年統一六國，建立郡縣制，統一文字、度量衡與貨幣，陵墓旁埋有兵馬俑。",en:"Born in Handan, he unified China in 221 BC, created a system of commanderies and standardised writing, weights and coinage; the Terracotta Army guards his tomb."}},
{id:"liu-bang",y:[-256,-195],at:["xian"],c:[116.93,34.73],pl:{en:"Pei",zh:"沛縣"},n:{zh:"劉邦（漢高祖）",en:"Liu Bang (Emperor Gaozu of Han)"},r:{zh:"漢朝開國皇帝",en:"Founder of the Han dynasty"},d:{zh:"出身平民，秦末起兵，擊敗項羽後建立漢朝，定都長安。",en:"A commoner who rose in revolt against Qin, defeated Xiang Yu and founded the Han dynasty with its capital at Chang’an."}},
{id:"han-wudi",y:[-156,-87],at:["xian","dunhuang"],n:{zh:"漢武帝",en:"Emperor Wu of Han"},r:{zh:"漢朝皇帝",en:"Han emperor"},d:{zh:"在位五十四年，北擊匈奴，設河西四郡，派張騫出使西域，獨尊儒術。",en:"Reigned for fifty-four years, fought the Xiongnu, set up the Hexi commanderies including Dunhuang, sent Zhang Qian to Central Asia and made Confucianism the state teaching."}},
{id:"zhang-qian",y:[-164,-113],ca:1,at:["xian","dunhuang","kashgar"],n:{zh:"張騫",en:"Zhang Qian"},r:{zh:"外交家、探險家",en:"Envoy and explorer"},d:{zh:"奉漢武帝之命出使西域，兩度被匈奴扣留，抵達大宛、大夏等地，被視為絲綢之路的開拓者。",en:"Sent west by Emperor Wu, twice held captive by the Xiongnu, he reached Ferghana and Bactria and is regarded as the pioneer of the Silk Road."}},
{id:"sima-qian",y:[-145,-86],ca:1,at:["xian"],n:{zh:"司馬遷",en:"Sima Qian"},r:{zh:"史學家",en:"Historian"},d:{zh:"西漢太史令，受宮刑後發憤完成《史記》，開創紀傳體史書。",en:"Grand Historian of the Western Han who, after being sentenced to castration, completed the Records of the Grand Historian, the model for Chinese official histories."}},
{id:"cao-cao",y:[155,220],at:["luoyang"],c:[115.78,33.85],pl:{en:"Bozhou",zh:"亳州"},n:{zh:"曹操",en:"Cao Cao"},r:{zh:"東漢末年權臣、詩人",en:"Warlord and poet"},d:{zh:"挾天子以令諸侯，統一北方，為曹魏奠定基礎，也是建安文學的代表詩人，卒於洛陽。",en:"Controlled the last Han emperor, united northern China and laid the foundations of Cao Wei; also a leading poet, he died in Luoyang."}},
{id:"liu-bei",y:[161,223],at:["chengdu"],c:[115.97,39.48],pl:{en:"Zhuozhou",zh:"涿州"},n:{zh:"劉備",en:"Liu Bei"},r:{zh:"蜀漢開國皇帝",en:"Founder of Shu Han"},d:{zh:"漢室宗親，三顧茅廬請出諸葛亮，入蜀後於 221 年在成都稱帝。",en:"A distant member of the Han royal house who recruited Zhuge Liang, took Shu and proclaimed himself emperor at Chengdu in 221."}},
{id:"zhuge-liang",y:[181,234],at:["chengdu"],n:{zh:"諸葛亮",en:"Zhuge Liang"},r:{zh:"蜀漢丞相",en:"Chancellor of Shu Han"},d:{zh:"輔佐劉備父子，六出祁山北伐曹魏，病逝於五丈原，被後世視為忠臣與智者的典範。",en:"Served Liu Bei and his son as chancellor and led repeated northern campaigns against Wei; he died at Wuzhang Plains and became China’s model of loyalty and wisdom."}},
{id:"wang-xizhi",y:[303,361],at:["nanjing"],c:[120.58,30.00],pl:{en:"Shaoxing",zh:"紹興"},n:{zh:"王羲之",en:"Wang Xizhi"},r:{zh:"書法家",en:"Calligrapher"},d:{zh:"東晉書法家，被尊為“書聖”，《蘭亭集序》寫於會稽（今紹興）。",en:"Calligrapher of the Eastern Jin known as the ‘Sage of Calligraphy’; he wrote the Lanting Preface at Kuaiji, today’s Shaoxing."}},
{id:"tang-taizong",y:[598,649],at:["xian"],n:{zh:"唐太宗",en:"Emperor Taizong of Tang"},r:{zh:"唐朝皇帝",en:"Tang emperor"},d:{zh:"李世民，玄武門之變後即位，開創“貞觀之治”，被西北諸族尊為“天可汗”。",en:"Li Shimin, who took the throne after the Xuanwu Gate incident, presided over the Zhenguan era and was hailed by the steppe peoples as ‘Heavenly Khan’."}},
{id:"xuanzang",y:[602,664],at:["xian","dunhuang","taxila","patna"],c:[112.77,34.62],pl:{en:"Yanshi, near Luoyang",zh:"洛陽偃師"},n:{zh:"玄奘",en:"Xuanzang"},r:{zh:"高僧、翻譯家",en:"Buddhist monk and translator"},d:{zh:"從長安西行求法，在那爛陀寺學習多年，攜經卷返回長安翻譯，口述成《大唐西域記》。",en:"Left Chang’an for India, studied for years at Nalanda, returned with hundreds of scriptures to translate, and dictated the Great Tang Records on the Western Regions."}},
{id:"wu-zetian",y:[624,705],at:["luoyang","xian"],n:{zh:"武則天",en:"Wu Zetian"},r:{zh:"中國唯一的女皇帝",en:"China’s only empress regnant"},d:{zh:"唐高宗的皇后，690 年稱帝建立武周，以洛陽為“神都”，晚年被迫退位。",en:"Empress of Gaozong of Tang who in 690 declared her own Zhou dynasty, ruled from Luoyang as the ‘divine capital’ and was forced to abdicate at the end of her life."}},
{id:"li-bai",y:[701,762],at:["xian"],c:[74.99,42.84],pl:{en:"Suyab (by tradition)",zh:"碎葉（一說）"},n:{zh:"李白",en:"Li Bai"},r:{zh:"詩人",en:"Poet"},d:{zh:"盛唐浪漫主義詩人，號“詩仙”，曾在長安供奉翰林，一生漫遊各地。",en:"Romantic poet of the high Tang, the ‘Immortal of Poetry’, who served briefly at court in Chang’an and spent his life wandering."}},
{id:"du-fu",y:[712,770],at:["chengdu","xian","luoyang"],n:{zh:"杜甫",en:"Du Fu"},r:{zh:"詩人",en:"Poet"},d:{zh:"號“詩聖”，經歷安史之亂，詩作記錄時代苦難，在成都草堂居住數年。",en:"The ‘Sage of Poetry’, whose verse records the suffering of the An Lushan rebellion; he lived for several years in a thatched cottage in Chengdu."}},
{id:"song-taizu",y:[927,976],at:["kaifeng","luoyang"],n:{zh:"趙匡胤（宋太祖）",en:"Zhao Kuangyin (Emperor Taizu of Song)"},r:{zh:"宋朝開國皇帝",en:"Founder of the Song dynasty"},d:{zh:"後周禁軍統帥，960 年陳橋兵變黃袍加身，建立宋朝，定都開封，以“杯酒釋兵權”削弱武將。",en:"Commander of the Later Zhou guards who was proclaimed emperor by his troops in 960, founded the Song with its capital at Kaifeng and curbed the power of the generals."}},
{id:"su-shi",y:[1037,1101],at:["hangzhou","kaifeng"],c:[103.83,30.05],pl:{en:"Meishan",zh:"眉山"},n:{zh:"蘇軾",en:"Su Shi"},r:{zh:"文學家、書畫家",en:"Writer, painter and calligrapher"},d:{zh:"北宋文豪，詩詞書畫皆精，兩任杭州地方官，修築西湖蘇堤，屢遭貶謫。",en:"Song writer, painter and calligrapher who twice governed Hangzhou, built the Su Causeway on West Lake and was repeatedly sent into exile."}},
{id:"yue-fei",y:[1103,1142],at:["hangzhou","kaifeng"],c:[114.38,35.90],pl:{en:"Tangyin",zh:"湯陰"},n:{zh:"岳飛",en:"Yue Fei"},r:{zh:"南宋將領",en:"Southern Song general"},d:{zh:"抗金名將，北伐屢勝，卻被召回並以“莫須有”罪名在臨安被害，後世奉為民族英雄。",en:"General who won repeated victories against the Jin but was recalled and put to death in Lin’an (Hangzhou) on false charges; he is honoured as a national hero."}},
{id:"genghis-khan",y:[1162,1227],ca:1,at:["karakorum","bukhara","beijing"],n:{zh:"成吉思汗",en:"Genghis Khan"},r:{zh:"蒙古帝國創建者",en:"Founder of the Mongol Empire"},d:{zh:"鐵木真於 1206 年統一蒙古各部，被尊為成吉思汗，此後攻金、滅西夏、西征花剌子模，奠定了蒙古帝國。",en:"Temüjin united the Mongol tribes in 1206 as Genghis Khan and went on to attack the Jin, destroy the Western Xia and conquer Khwarazm, founding the Mongol Empire."}},
{id:"kublai-khan",y:[1215,1294],at:["beijing","karakorum","hangzhou"],n:{zh:"忽必烈",en:"Kublai Khan"},r:{zh:"元朝開國皇帝",en:"Founder of the Yuan dynasty"},d:{zh:"成吉思汗之孫，1271 年建立元朝，定都大都（今北京），1279 年滅南宋統一中國。",en:"Grandson of Genghis Khan who proclaimed the Yuan dynasty in 1271, built his capital Dadu (Beijing) and conquered the Southern Song in 1279."}},
{id:"hongwu",y:[1328,1398],at:["nanjing"],c:[117.37,32.94],pl:{en:"Fengyang",zh:"鳳陽"},n:{zh:"朱元璋（明太祖）",en:"Zhu Yuanzhang (Hongwu Emperor)"},r:{zh:"明朝開國皇帝",en:"Founder of the Ming dynasty"},d:{zh:"出身貧農，曾為僧人，元末起兵，1368 年在南京稱帝建立明朝，將元朝逐出中原。",en:"A poor peasant and former monk who rose in the rebellions against the Yuan and founded the Ming at Nanjing in 1368, driving the Mongols from China."}},
{id:"yongle",y:[1360,1424],at:["beijing","nanjing"],n:{zh:"朱棣（明成祖）",en:"Zhu Di (Yongle Emperor)"},r:{zh:"明朝皇帝",en:"Ming emperor"},d:{zh:"靖難之役奪取皇位，遷都北京並營建紫禁城，派鄭和下西洋，編纂《永樂大典》。",en:"Seized the throne in civil war, moved the capital to Beijing and built the Forbidden City, sent Zheng He’s fleets abroad and commissioned the Yongle Encyclopedia."}},
{id:"zheng-he",y:[1371,1433],at:["nanjing","malacca","calicut","mogadishu"],c:[102.62,24.68],pl:{en:"Kunyang, Yunnan",zh:"雲南昆陽"},n:{zh:"鄭和",en:"Zheng He"},r:{zh:"航海家",en:"Admiral and explorer"},d:{zh:"雲南回族人，1405 年至 1433 年七次率船隊從南京出發下西洋，遠達東非。",en:"Muslim from Yunnan who between 1405 and 1433 led seven great fleets from Nanjing across the Indian Ocean as far as East Africa."}},
{id:"matteo-ricci",y:[1552,1610],at:["macau","beijing"],c:[13.45,43.30],pl:{en:"Macerata",zh:"馬切拉塔"},n:{zh:"利瑪竇",en:"Matteo Ricci"},r:{zh:"耶穌會傳教士",en:"Jesuit missionary"},d:{zh:"意大利耶穌會士，經澳門進入中國，在北京傳教，與徐光啟合譯《幾何原本》，繪製《坤輿萬國全圖》。",en:"Italian Jesuit who entered China through Macau, worked in Beijing, translated Euclid with Xu Guangqi and drew a great world map for Chinese readers."}},
{id:"kangxi",y:[1654,1722],at:["beijing"],n:{zh:"康熙帝",en:"Kangxi Emperor"},r:{zh:"清朝皇帝",en:"Qing emperor"},d:{zh:"在位六十一年，平定三藩、收復臺灣，與俄國簽訂《尼布楚條約》。",en:"Reigned for sixty-one years, crushed the Three Feudatories, took Taiwan and signed the Treaty of Nerchinsk with Russia."}},
{id:"qianlong",y:[1711,1799],at:["beijing","kashgar"],n:{zh:"乾隆帝",en:"Qianlong Emperor"},r:{zh:"清朝皇帝",en:"Qing emperor"},d:{zh:"清朝疆域在其治下達到最大，平定準噶爾與回部，1793 年接見馬戛爾尼使團。",en:"Under him the Qing reached its greatest extent with the conquest of Dzungaria and the Tarim Basin; he received the Macartney embassy in 1793."}},
{id:"lin-zexu",y:[1785,1850],at:["guangzhou"],c:[119.30,26.08],pl:{en:"Fuzhou",zh:"福州"},n:{zh:"林則徐",en:"Lin Zexu"},r:{zh:"清朝官員",en:"Qing official"},d:{zh:"1839 年在廣州主持虎門銷煙，此事成為第一次鴉片戰爭的導火索。",en:"Destroyed the British opium stocks at Humen near Guangzhou in 1839, an act that led to the First Opium War."}},
{id:"cixi",y:[1835,1908],at:["beijing"],n:{zh:"慈禧太后",en:"Empress Dowager Cixi"},r:{zh:"清朝實際統治者",en:"De facto ruler of Qing China"},d:{zh:"咸豐帝的妃子，同治、光緒兩朝垂簾聽政近半個世紀，1898 年鎮壓戊戌變法。",en:"Consort of the Xianfeng Emperor who controlled the Qing government for almost half a century and crushed the reform movement of 1898."}},
{id:"sun-yat-sen",y:[1866,1925],at:["guangzhou","nanjing","hongkong"],c:[113.53,22.43],pl:{en:"Cuiheng, Zhongshan",zh:"中山翠亨村"},n:{zh:"孫中山",en:"Sun Yat-sen"},r:{zh:"中華民國創建者",en:"Founder of the Republic of China"},d:{zh:"曾在香港學醫，領導推翻清朝的革命，1912 年在南京就任臨時大總統，提出三民主義。",en:"Studied medicine in Hong Kong, led the revolution against the Qing, became provisional president in Nanjing in 1912 and set out the Three Principles of the People."}},
// ---- Japan & Korea ----
{id:"prince-shotoku",y:[574,622],at:["nara"],n:{zh:"聖德太子",en:"Prince Shōtoku"},r:{zh:"日本攝政",en:"Regent of Japan"},d:{zh:"推古天皇的攝政，制定《十七條憲法》，派遣遣隋使，創建法隆寺。",en:"Regent for Empress Suiko who issued the Seventeen-Article Constitution, sent envoys to Sui China and founded Hōryū-ji."}},
{id:"wang-geon",y:[877,943],at:["kaesong"],n:{zh:"王建（高麗太祖）",en:"Wang Geon (Taejo of Goryeo)"},r:{zh:"高麗開國君主",en:"Founder of Goryeo"},d:{zh:"918 年建立高麗，定都開京，935 年接受新羅投降，次年統一後三國。",en:"Founded Goryeo in 918 with its capital at Gaegyeong, accepted Silla’s surrender in 935 and reunited the peninsula the following year."}},
{id:"murasaki-shikibu",y:[973,1014],ca:1,at:["kyoto"],n:{zh:"紫式部",en:"Murasaki Shikibu"},r:{zh:"作家",en:"Writer"},d:{zh:"平安時代宮廷女官，所著《源氏物語》被視為世界上最早的長篇小說之一。",en:"Lady-in-waiting at the Heian court whose Tale of Genji is counted among the world’s first novels."}},
{id:"minamoto-no-yoritomo",y:[1147,1199],at:["kamakura","kyoto"],n:{zh:"源賴朝",en:"Minamoto no Yoritomo"},r:{zh:"鎌倉幕府將軍",en:"First Kamakura shogun"},d:{zh:"在源平合戰中擊敗平氏，1192 年受封徵夷大將軍，開創日本延續近七百年的幕府政治。",en:"Defeated the Taira in the Genpei War and in 1192 became shogun, beginning nearly seven centuries of warrior government in Japan."}},
{id:"sejong",y:[1397,1450],at:["seoul"],n:{zh:"世宗大王",en:"Sejong the Great"},r:{zh:"朝鮮國王",en:"King of Joseon"},d:{zh:"朝鮮王朝第四代國王，主持創制韓文字母“訓民正音”，推動天文與農業研究。",en:"Fourth king of Joseon who created the Korean alphabet, Hangul, and promoted astronomy and agricultural science."}},
{id:"oda-nobunaga",y:[1534,1582],at:["kyoto"],c:[136.91,35.18],pl:{en:"Owari (Nagoya)",zh:"尾張（名古屋）"},n:{zh:"織田信長",en:"Oda Nobunaga"},r:{zh:"戰國大名",en:"Warlord"},d:{zh:"以火槍戰術統一日本中部，1573 年驅逐末代足利將軍，1582 年在京都本能寺遭家臣明智光秀襲擊自盡。",en:"Used firearms to conquer central Japan, ended the Ashikaga shogunate in 1573 and died in 1582 when his vassal Akechi Mitsuhide attacked him at Honnō-ji in Kyoto."}},
{id:"toyotomi-hideyoshi",y:[1537,1598],at:["osaka","kyoto"],n:{zh:"豐臣秀吉",en:"Toyotomi Hideyoshi"},r:{zh:"日本統一者",en:"Unifier of Japan"},d:{zh:"足輕出身，繼承織田信長事業統一日本，修築大阪城，兩次出兵朝鮮。",en:"Rose from the ranks to complete Nobunaga’s unification of Japan, built Osaka Castle and twice invaded Korea."}},
{id:"yi-sun-sin",y:[1545,1598],at:["seoul"],n:{zh:"李舜臣",en:"Yi Sun-sin"},r:{zh:"朝鮮水軍將領",en:"Korean admiral"},d:{zh:"壬辰戰爭中以龜船屢敗日本水軍，1598 年在露梁海戰中陣亡。",en:"Defeated the Japanese navy again and again with his turtle ships in the Imjin War and was killed at the Battle of Noryang in 1598."}},
{id:"tokugawa-ieyasu",y:[1543,1616],at:["tokyo","osaka","kyoto"],c:[137.16,34.96],pl:{en:"Okazaki",zh:"岡崎"},n:{zh:"德川家康",en:"Tokugawa Ieyasu"},r:{zh:"江戶幕府將軍",en:"First Tokugawa shogun"},d:{zh:"關原之戰獲勝，1603 年在江戶開創德川幕府，1615 年攻滅豐臣氏，此後日本和平兩百餘年。",en:"Won at Sekigahara, founded the Tokugawa shogunate at Edo in 1603 and destroyed the Toyotomi at Osaka in 1615, opening more than two centuries of peace."}},
{id:"emperor-meiji",y:[1852,1912],at:["tokyo","kyoto"],n:{zh:"明治天皇",en:"Emperor Meiji"},r:{zh:"日本天皇",en:"Emperor of Japan"},d:{zh:"在位期間幕府倒臺，從京都遷居東京，日本推行明治維新，迅速工業化並對外擴張。",en:"Under him the shogunate fell, the court moved from Kyoto to Tokyo and Japan rapidly modernised and expanded in the Meiji Restoration."}},
// ---- South & South-East Asia ----
{id:"buddha",y:[-563,-483],ca:1,at:["varanasi","patna"],c:[83.28,27.48],pl:{en:"Lumbini",zh:"藍毗尼"},n:{zh:"釋迦牟尼",en:"Siddhartha Gautama, the Buddha"},r:{zh:"佛教創始人",en:"Founder of Buddhism"},d:{zh:"釋迦族王子，出家修行後在菩提伽耶悟道，於瓦拉納西郊外鹿野苑初轉法輪。傳統年代存在爭議。",en:"Prince of the Shakya clan who renounced his life, reached enlightenment at Bodh Gaya and preached his first sermon at Sarnath near Varanasi. His dates are disputed."}},
{id:"chandragupta-maurya",y:[-340,-297],ca:1,at:["patna","taxila"],n:{zh:"旃陀羅笈多",en:"Chandragupta Maurya"},r:{zh:"孔雀王朝創建者",en:"Founder of the Maurya Empire"},d:{zh:"推翻難陀王朝，以華氏城為都，擊退塞琉古一世，建立統一北印度的孔雀帝國。",en:"Overthrew the Nanda kings, ruled from Pataliputra, held off Seleucus I and founded the Maurya Empire across northern India."}},
{id:"ashoka",y:[-304,-232],ca:1,at:["patna","ujjain"],n:{zh:"阿育王",en:"Ashoka"},r:{zh:"孔雀王朝皇帝",en:"Maurya emperor"},d:{zh:"征服羯陵伽後痛悔殺戮，皈依佛教，在各地立石柱刻詔，並派人四方弘法。",en:"After the bloody conquest of Kalinga he turned to Buddhism, carved edicts on pillars and rocks across his empire and sent missionaries abroad."}},
{id:"anawrahta",y:[1014,1077],at:["bagan"],n:{zh:"阿奴律陀",en:"Anawrahta"},r:{zh:"蒲甘國王",en:"King of Pagan"},d:{zh:"統一緬甸的第一位國王，引入上座部佛教，開啟蒲甘的建塔時代。",en:"First king to unite Burma, who brought Theravada Buddhism to Bagan and began its age of temple building."}},
{id:"jayavarman-vii",y:[1122,1218],ca:1,at:["angkor"],n:{zh:"闍耶跋摩七世",en:"Jayavarman VII"},r:{zh:"高棉國王",en:"Khmer king"},d:{zh:"擊退佔婆後重建吳哥，修建吳哥通王城與巴戎寺，信奉大乘佛教。",en:"Drove out the Cham, rebuilt Angkor with the walled city of Angkor Thom and the Bayon, and favoured Mahayana Buddhism."}},
{id:"krishnadevaraya",y:[1471,1529],at:["vijayanagara"],n:{zh:"克里希納德瓦·拉亞",en:"Krishnadevaraya"},r:{zh:"毗奢耶那伽羅皇帝",en:"Emperor of Vijayanagara"},d:{zh:"毗奢耶那伽羅帝國最著名的君主，屢敗德干諸蘇丹國，宮廷文學繁榮，葡萄牙人留下了對其都城的記述。",en:"The most celebrated ruler of Vijayanagara, who defeated the Deccan sultanates and patronised literature; Portuguese visitors described his capital."}},
{id:"babur",y:[1483,1530],at:["kabul","agra","samarkand"],c:[72.79,40.38],pl:{en:"Andijan",zh:"安集延"},n:{zh:"巴布爾",en:"Babur"},r:{zh:"莫臥兒帝國創建者",en:"Founder of the Mughal Empire"},d:{zh:"帖木兒與成吉思汗的後裔，失去撒馬爾罕後據有喀布爾，1526 年在帕尼帕特獲勝，建立莫臥兒帝國；自傳《巴布爾回憶錄》傳世。",en:"Descendant of Timur and Genghis Khan who lost Samarkand, ruled from Kabul and in 1526 won at Panipat to found the Mughal Empire; his memoirs survive."}},
{id:"akbar",y:[1542,1605],at:["agra","lahore","delhi"],n:{zh:"阿克巴",en:"Akbar"},r:{zh:"莫臥兒皇帝",en:"Mughal emperor"},d:{zh:"莫臥兒帝國最偉大的皇帝，擴張疆土，推行宗教寬容，建立高效的行政制度。",en:"The greatest Mughal emperor, who expanded the empire, practised religious tolerance and built an effective administration."}},
{id:"shah-jahan",y:[1592,1666],at:["agra","delhi","lahore"],n:{zh:"沙賈汗",en:"Shah Jahan"},r:{zh:"莫臥兒皇帝",en:"Mughal emperor"},d:{zh:"為紀念亡妻修建泰姬陵，營建德里紅堡，晚年被兒子奧朗則布囚禁於阿格拉堡。",en:"Built the Taj Mahal for his late wife and the Red Fort in Delhi; in old age he was imprisoned in the Agra Fort by his son Aurangzeb."}},
{id:"aurangzeb",y:[1618,1707],at:["delhi","agra"],n:{zh:"奧朗則布",en:"Aurangzeb"},r:{zh:"莫臥兒皇帝",en:"Mughal emperor"},d:{zh:"在位期間莫臥兒版圖最大，但長年征戰德干與嚴苛的宗教政策削弱了帝國。",en:"Ruled the Mughal Empire at its largest, but decades of war in the Deccan and strict religious policies weakened it."}},
{id:"ranjit-singh",y:[1780,1839],at:["lahore"],n:{zh:"蘭吉特·辛格",en:"Ranjit Singh"},r:{zh:"錫克帝國君主",en:"Maharaja of the Sikh Empire"},d:{zh:"1799 年攻取拉合爾，統一旁遮普，建立錫克帝國，為阿姆利則金廟貼金。",en:"Took Lahore in 1799, united the Punjab in the Sikh Empire and covered the Golden Temple at Amritsar with gold."}},
{id:"raffles",y:[1781,1826],at:["singapore","jakarta"],n:{zh:"斯坦福·萊佛士",en:"Stamford Raffles"},r:{zh:"英國殖民官員",en:"British colonial official"},d:{zh:"拿破崙戰爭期間管理爪哇，1819 年為東印度公司在新加坡建立商站。",en:"Governed Java during the Napoleonic Wars and in 1819 founded a trading post at Singapore for the East India Company."}},
{id:"chulalongkorn",y:[1853,1910],at:["bangkok"],n:{zh:"朱拉隆功（拉瑪五世）",en:"Chulalongkorn (Rama V)"},r:{zh:"暹羅國王",en:"King of Siam"},d:{zh:"廢除奴隸制、改革政府，在英法之間周旋，使暹羅保持獨立。",en:"Abolished slavery, reformed the government and played Britain and France against each other to keep Siam independent."}},
{id:"tagore",y:[1861,1941],at:["kolkata"],n:{zh:"羅賓德拉納特·泰戈爾",en:"Rabindranath Tagore"},r:{zh:"詩人",en:"Poet"},d:{zh:"加爾各答出生的孟加拉詩人，1913 年成為第一位獲得諾貝爾文學獎的亞洲人。",en:"Bengali poet from Calcutta who in 1913 became the first Asian to win the Nobel Prize in Literature."}},
{id:"rizal",y:[1861,1896],at:["manila"],c:[121.17,14.21],pl:{en:"Calamba",zh:"卡蘭巴"},n:{zh:"何塞·黎剎",en:"José Rizal"},r:{zh:"菲律賓民族英雄",en:"Filipino national hero"},d:{zh:"醫生和作家，小說《不許犯我》揭露西班牙殖民統治，1896 年在馬尼拉被處決。",en:"Doctor and novelist whose Noli Me Tángere exposed Spanish colonial rule; he was executed in Manila in 1896."}},
{id:"gandhi",y:[1869,1948],at:["mumbai","delhi"],c:[69.61,21.64],pl:{en:"Porbandar",zh:"博爾本德爾"},n:{zh:"甘地",en:"Mahatma Gandhi"},r:{zh:"印度獨立運動領袖",en:"Leader of Indian independence"},d:{zh:"以非暴力不合作運動領導印度爭取獨立，1948 年在德里遇刺。",en:"Led India’s struggle for independence through non-violent resistance and was assassinated in Delhi in 1948."}},
{id:"jinnah",y:[1876,1948],at:["mumbai","lahore"],c:[67.01,24.86],pl:{en:"Karachi",zh:"卡拉奇"},n:{zh:"穆罕默德·阿里·真納",en:"Muhammad Ali Jinnah"},r:{zh:"巴基斯坦國父",en:"Founder of Pakistan"},d:{zh:"在孟買執業的律師，領導全印穆斯林聯盟，1947 年巴基斯坦建國後任首任總督。",en:"Bombay lawyer who led the All-India Muslim League and became Pakistan’s first governor-general in 1947."}},
{id:"nehru",y:[1889,1964],at:["delhi"],c:[81.85,25.44],pl:{en:"Allahabad",zh:"阿拉哈巴德"},n:{zh:"賈瓦哈拉爾·尼赫魯",en:"Jawaharlal Nehru"},r:{zh:"印度首任總理",en:"First prime minister of India"},d:{zh:"國大黨領袖，1947 年起任印度總理至去世，是不結盟運動的倡導者之一。",en:"Congress leader who served as India’s prime minister from 1947 until his death and was a founder of the Non-Aligned Movement."}},
{id:"ho-chi-minh",y:[1890,1969],at:["hanoi","saigon","hue"],n:{zh:"胡志明",en:"Ho Chi Minh"},r:{zh:"越南革命領袖",en:"Vietnamese revolutionary leader"},d:{zh:"1945 年在河內宣佈越南獨立，領導抗法與抗美戰爭；西貢在 1976 年以他的名字命名。",en:"Declared Vietnam’s independence in Hanoi in 1945 and led the wars against France and the United States; Saigon was renamed after him in 1976."}},
// ---- Africa ----
{id:"ezana",y:[320,360],ca:1,at:["axum","meroe"],n:{zh:"埃扎納",en:"Ezana of Aksum"},r:{zh:"阿克蘇姆國王",en:"King of Aksum"},d:{zh:"阿克蘇姆第一位信奉基督教的國王，在錢幣與碑銘上使用十字，曾遠征麥羅埃。",en:"The first Christian king of Aksum, who put the cross on his coins and inscriptions and campaigned against Meroë."}},
{id:"mansa-musa",y:[1280,1337],ca:1,at:["timbuktu","gao","cairo","mecca"],n:{zh:"曼薩·穆薩",en:"Mansa Musa"},r:{zh:"馬裡帝國皇帝",en:"Emperor of Mali"},d:{zh:"1324 年赴麥加朝覲，途經開羅時大量散發黃金，使馬裡聞名於地中海世界；在廷巴克圖修建清真寺。",en:"Made the pilgrimage to Mecca in 1324, spending so much gold in Cairo that Mali became famous around the Mediterranean; he built mosques in Timbuktu."}},
{id:"askia-muhammad",y:[1443,1538],ca:1,at:["gao","timbuktu"],n:{zh:"阿斯基亞·穆罕默德",en:"Askia Muhammad"},r:{zh:"桑海帝國皇帝",en:"Emperor of Songhai"},d:{zh:"奪取桑海王位後擴張帝國，推行伊斯蘭行政改革，葬於加奧的金字塔形陵墓。",en:"Seized the Songhai throne, expanded the empire and reformed its government on Islamic lines; he is buried in the pyramid tomb at Gao."}},
{id:"nzinga",y:[1583,1663],ca:1,at:["luanda"],n:{zh:"恩津加女王",en:"Queen Nzinga"},r:{zh:"恩東戈與馬坦巴女王",en:"Queen of Ndongo and Matamba"},d:{zh:"1622 年出使羅安達與葡萄牙人談判，此後數十年領導抵抗葡萄牙殖民擴張。",en:"Negotiated with the Portuguese at Luanda in 1622 and for decades afterwards led resistance to their expansion."}},
{id:"osei-tutu",y:[1660,1717],ca:1,at:["kumasi"],n:{zh:"奧塞·圖圖",en:"Osei Tutu"},r:{zh:"阿散蒂帝國創建者",en:"Founder of the Asante Empire"},d:{zh:"以庫馬西為都聯合阿肯諸邦，建立阿散蒂帝國；“金凳子”成為國家統一的象徵。",en:"United the Akan states around Kumasi into the Asante Empire, with the Golden Stool as the symbol of the nation."}},
{id:"menelik-ii",y:[1844,1913],at:["addis","gondar"],n:{zh:"孟尼利克二世",en:"Menelik II"},r:{zh:"埃塞俄比亞皇帝",en:"Emperor of Ethiopia"},d:{zh:"建立亞的斯亞貝巴，1896 年在阿杜瓦擊敗意大利，使埃塞俄比亞保持獨立。",en:"Founded Addis Ababa and defeated Italy at Adwa in 1896, keeping Ethiopia independent."}},
{id:"haile-selassie",y:[1892,1975],at:["addis"],n:{zh:"海爾·塞拉西一世",en:"Haile Selassie I"},r:{zh:"埃塞俄比亞皇帝",en:"Emperor of Ethiopia"},d:{zh:"1930 年加冕，意大利入侵期間流亡，1941 年復位，推動成立非洲統一組織，1974 年被推翻。",en:"Crowned in 1930, exiled during the Italian occupation and restored in 1941; he helped found the Organisation of African Unity and was overthrown in 1974."}},
{id:"kenyatta",y:[1897,1978],ca:1,at:["nairobi"],n:{zh:"喬莫·肯雅塔",en:"Jomo Kenyatta"},r:{zh:"肯尼亞首任總統",en:"First president of Kenya"},d:{zh:"肯尼亞民族主義領袖，茅茅起義期間被英國當局監禁，1964 年起任肯尼亞總統。",en:"Kenyan nationalist leader imprisoned by the British during the Mau Mau rising; he became president of Kenya in 1964."}},
{id:"nkrumah",y:[1909,1972],at:[],c:[-0.19,5.56],pl:{en:"Accra",zh:"阿克拉"},n:{zh:"克瓦米·恩克魯瑪",en:"Kwame Nkrumah"},r:{zh:"加納首任總統",en:"First leader of Ghana"},d:{zh:"領導黃金海岸於 1957 年獨立為加納，成為撒哈拉以南第一個擺脫殖民統治的國家，倡導泛非主義。",en:"Led the Gold Coast to independence as Ghana in 1957, the first colony south of the Sahara to break free, and championed pan-Africanism."}},
{id:"mandela",y:[1918,2013],at:["johannesburg","capetown"],c:[28.78,-31.95],pl:{en:"Mvezo",zh:"姆維佐"},n:{zh:"納爾遜·曼德拉",en:"Nelson Mandela"},r:{zh:"南非總統",en:"President of South Africa"},d:{zh:"反種族隔離運動領袖，在羅本島等地坐牢二十七年，1994 年當選南非首位黑人總統。",en:"Leader of the struggle against apartheid who spent twenty-seven years in prison, much of it on Robben Island, and in 1994 became South Africa’s first black president."}},
// ---- Americas ----
{id:"pachacuti",y:[1418,1471],ca:1,at:["cusco"],n:{zh:"帕查庫特克",en:"Pachacuti"},r:{zh:"印加皇帝",en:"Sapa Inca"},d:{zh:"擊退昌卡人後即位，將庫斯科小國擴張為印加帝國，重建庫斯科並修建馬丘比丘。",en:"Took power after defeating the Chanka, turned the small state of Cusco into the Inca Empire, rebuilt the capital and built Machu Picchu."}},
{id:"moctezuma-ii",y:[1466,1520],ca:1,at:["mexicocity"],n:{zh:"蒙特蘇馬二世",en:"Moctezuma II"},r:{zh:"阿茲特克皇帝",en:"Aztec emperor"},d:{zh:"阿茲特克帝國鼎盛時的統治者，1519 年接待科爾特斯，後被西班牙人扣押，在動亂中死去。",en:"Ruler of the Aztec Empire at its height who received Cortés in 1519, was held hostage by the Spanish and died in the fighting that followed."}},
{id:"cortes",y:[1485,1547],at:["mexicocity","seville"],c:[-5.96,38.97],pl:{en:"Medellín",zh:"梅德林"},n:{zh:"埃爾南·科爾特斯",en:"Hernán Cortés"},r:{zh:"西班牙征服者",en:"Spanish conquistador"},d:{zh:"1519 年率數百人登陸墨西哥，聯合特拉斯卡拉等族於 1521 年攻陷特諾奇蒂特蘭。",en:"Landed in Mexico in 1519 with a few hundred men and, allied with the Tlaxcalans and others, took Tenochtitlan in 1521."}},
{id:"pizarro",y:[1478,1541],ca:1,at:["lima","cusco"],c:[-5.88,39.46],pl:{en:"Trujillo, Spain",zh:"西班牙特魯希略"},n:{zh:"弗朗西斯科·皮薩羅",en:"Francisco Pizarro"},r:{zh:"西班牙征服者",en:"Spanish conquistador"},d:{zh:"1532 年在卡哈馬卡俘獲印加皇帝阿塔瓦爾帕，征服印加帝國，建立利馬，後在利馬被政敵刺殺。",en:"Captured the Inca emperor Atahualpa at Cajamarca in 1532, conquered the Inca Empire and founded Lima, where rivals later killed him."}},
{id:"atahualpa",y:[1502,1533],ca:1,at:["quito","cusco"],n:{zh:"阿塔瓦爾帕",en:"Atahualpa"},r:{zh:"印加皇帝",en:"Sapa Inca"},d:{zh:"在內戰中擊敗兄長瓦斯卡爾，剛成為印加皇帝就被皮薩羅俘虜，交付贖金後仍被處死。",en:"Defeated his brother Huáscar in civil war and had just become emperor when Pizarro captured him; he was executed despite paying a huge ransom."}},
{id:"champlain",y:[1574,1635],ca:1,at:["quebec","montreal"],n:{zh:"薩繆爾·德·尚普蘭",en:"Samuel de Champlain"},r:{zh:"探險家",en:"Explorer"},d:{zh:"“新法蘭西之父”，1608 年建立魁北克，繪製了聖勞倫斯河與五大湖地區的地圖。",en:"The ‘Father of New France’, who founded Quebec in 1608 and mapped the St Lawrence and the Great Lakes."}},
{id:"sor-juana",y:[1648,1695],ca:1,at:["mexicocity"],n:{zh:"胡安娜·伊內斯·德拉克魯斯修女",en:"Sor Juana Inés de la Cruz"},r:{zh:"詩人、學者",en:"Poet and scholar"},d:{zh:"新西班牙的修女與詩人，自學成才，捍衛女性求學的權利，被視為西班牙語巴洛克文學的代表。",en:"Nun and poet of New Spain, largely self-taught, who defended women’s right to learning and is a leading voice of Spanish Baroque literature."}},
{id:"franklin",y:[1706,1790],at:["boston","philadelphia","paris"],n:{zh:"本傑明·富蘭克林",en:"Benjamin Franklin"},r:{zh:"科學家、政治家",en:"Scientist and statesman"},d:{zh:"生於波士頓，在費城從事印刷與電學研究，參與起草《獨立宣言》，出使法國爭取援助。",en:"Born in Boston, he printed and experimented with electricity in Philadelphia, helped draft the Declaration of Independence and won French support as envoy in Paris."}},
{id:"washington",y:[1732,1799],at:["philadelphia","washington","newyork"],c:[-76.94,38.19],pl:{en:"Westmoreland County, Virginia",zh:"弗吉尼亞威斯特摩蘭縣"},n:{zh:"喬治·華盛頓",en:"George Washington"},r:{zh:"美國首任總統",en:"First president of the United States"},d:{zh:"獨立戰爭中任大陸軍總司令，在約克鎮迫使英軍投降，1789 年就任首任總統。",en:"Commanded the Continental Army in the War of Independence, forced the British surrender at Yorktown and became the first president in 1789."}},
{id:"jefferson",y:[1743,1826],at:["philadelphia","washington","paris"],c:[-78.40,38.01],pl:{en:"Shadwell, Virginia",zh:"弗吉尼亞沙德韋爾"},n:{zh:"托馬斯·傑斐遜",en:"Thomas Jefferson"},r:{zh:"美國第三任總統",en:"Third president of the United States"},d:{zh:"1776 年在費城起草《獨立宣言》，任總統期間從法國購得路易斯安那。",en:"Drafted the Declaration of Independence in Philadelphia in 1776 and as president bought Louisiana from France."}},
{id:"tiradentes",y:[1746,1792],at:["ouropreto","rio"],n:{zh:"蒂拉登特斯",en:"Tiradentes"},r:{zh:"巴西獨立運動先驅",en:"Forerunner of Brazilian independence"},d:{zh:"米納斯密謀的成員，1792 年在里約熱內盧被處決，今為巴西民族英雄。",en:"Member of the Minas conspiracy, executed in Rio de Janeiro in 1792 and now a national hero of Brazil."}},
{id:"san-martin",y:[1778,1850],at:["buenosaires","santiago","lima"],c:[-56.87,-29.06],pl:{en:"Yapeyú",zh:"亞佩尤"},n:{zh:"何塞·德·聖馬丁",en:"José de San Martín"},r:{zh:"南美獨立運動領袖",en:"Leader of South American independence"},d:{zh:"率安第斯軍翻越安第斯山解放智利，1821 年在利馬宣佈秘魯獨立。",en:"Led the Army of the Andes across the mountains to free Chile and proclaimed Peru’s independence in Lima in 1821."}},
{id:"bolivar",y:[1783,1830],at:["caracas","bogota","quito","lima"],n:{zh:"西蒙·玻利瓦爾",en:"Simón Bolívar"},r:{zh:"南美獨立運動領袖",en:"Liberator of South America"},d:{zh:"生於加拉加斯，領導委內瑞拉、哥倫比亞、厄瓜多爾、秘魯和玻利維亞擺脫西班牙統治，被稱為“解放者”。",en:"Born in Caracas, he led Venezuela, Colombia, Ecuador, Peru and Bolivia to independence from Spain and is known as El Libertador."}},
{id:"juarez",y:[1806,1872],at:["mexicocity"],c:[-96.47,17.21],pl:{en:"Guelatao, Oaxaca",zh:"瓦哈卡格拉陶"},n:{zh:"貝尼托·華雷斯",en:"Benito Juárez"},r:{zh:"墨西哥總統",en:"President of Mexico"},d:{zh:"薩波特克人出身的總統，推行自由主義改革，領導抵抗法國干涉，1867 年處決馬克西米利安皇帝。",en:"Zapotec-born president who carried out liberal reforms, led resistance to the French intervention and had Emperor Maximilian executed in 1867."}},
{id:"lincoln",y:[1809,1865],at:["washington"],c:[-85.74,37.53],pl:{en:"Hodgenville, Kentucky",zh:"肯塔基霍真維爾"},n:{zh:"亞伯拉罕·林肯",en:"Abraham Lincoln"},r:{zh:"美國第十六任總統",en:"Sixteenth president of the United States"},d:{zh:"南北戰爭期間領導聯邦，1863 年發表《解放奴隸宣言》和葛底斯堡演說，戰爭結束時在華盛頓遇刺。",en:"Led the Union through the Civil War, issued the Emancipation Proclamation and gave the Gettysburg Address in 1863, and was assassinated in Washington as the war ended."}},
{id:"pedro-ii",y:[1825,1891],at:["rio"],n:{zh:"佩德羅二世",en:"Pedro II of Brazil"},r:{zh:"巴西皇帝",en:"Emperor of Brazil"},d:{zh:"五歲即位，在位近五十年，1888 年巴西廢除奴隸制，次年帝制被推翻。",en:"Became emperor at five and reigned for nearly fifty years; Brazil abolished slavery in 1888 and the monarchy fell the following year."}},
{id:"jose-marti",y:[1853,1895],at:["havana","newyork"],n:{zh:"何塞·馬蒂",en:"José Martí"},r:{zh:"古巴詩人、獨立運動領袖",en:"Cuban poet and independence leader"},d:{zh:"生於哈瓦那，長期流亡紐約組織古巴革命黨，1895 年返回古巴參戰陣亡。",en:"Born in Havana, he organised the Cuban Revolutionary Party in exile in New York and was killed in battle after returning to Cuba in 1895."}},
// ---- Oceania ----
{id:"abel-tasman",y:[1603,1659],at:["jakarta","hobart"],c:[6.60,53.25],pl:{en:"Lutjegast",zh:"呂特赫加斯特"},n:{zh:"阿貝爾·塔斯曼",en:"Abel Tasman"},r:{zh:"航海家",en:"Navigator"},d:{zh:"荷蘭東印度公司航海家，1642 年從巴達維亞出發，成為第一個到達塔斯馬尼亞和新西蘭的歐洲人。",en:"Dutch East India Company navigator who sailed from Batavia in 1642 and became the first European to reach Tasmania and New Zealand."}},
{id:"james-cook",y:[1728,1779],at:["sydney","honolulu","wellington"],c:[-1.24,54.56],pl:{en:"Marton, Yorkshire",zh:"約克郡馬頓"},n:{zh:"詹姆斯·庫克",en:"James Cook"},r:{zh:"航海家",en:"Navigator"},d:{zh:"三次太平洋航行，繪製新西蘭海圖，登陸澳大利亞東海岸植物學灣，1779 年在夏威夷被殺。",en:"Made three Pacific voyages, charted New Zealand, landed at Botany Bay on Australia’s east coast and was killed in Hawaiʻi in 1779."}},
{id:"kamehameha-i",y:[1758,1819],ca:1,at:["honolulu"],n:{zh:"卡美哈梅哈一世",en:"Kamehameha I"},r:{zh:"夏威夷國王",en:"King of Hawaiʻi"},d:{zh:"1795 年征服瓦胡島，1810 年統一夏威夷群島，建立夏威夷王國。",en:"Conquered Oʻahu in 1795 and by 1810 had united the Hawaiian Islands as a single kingdom."}},
];
